static void r21_settings_layout(unsigned int w,unsigned int h,int*x,int*y,unsigned int*pw,unsigned int*ph){
 *pw=w>700U?560U:w-32U;*ph=h>540U?420U:h-100U;*x=(int)w-(int)*pw-20;if(*x<16)*x=16;*y=64;
 /* Graphics stays inside the work area, above the existing dock. */
 if(g_settings_page==2&&h>=400U&&*ph>h-164U)*ph=h-164U;
}
/* R2 uses actual scanout dimensions for dock layout; never owns DRM state. */
static unsigned int g_r2_canvas_width;
