/* Aurora R5 — isolated, bounded 2x logical-surface raster path.  This is a
 * compatibility bridge for 3840x2160 on freestanding userspace; NOT native
 * 4K font rasterization, a GPU implementation or proven high frame rate.
 * Physical scanout remains DRM XRGB8888 and security/IPC ABIs are unchanged. */
#define NOVA_R5_MAX_LOGICAL_W 1920U
#define NOVA_R5_MAX_LOGICAL_H 1080U
static unsigned int g_r5_scale=1U;
static unsigned int g_r5_logical_w=0U;
static unsigned int g_r5_logical_h=0U;
static int g_r5_mouse_x_remainder=0;
static int g_r5_mouse_y_remainder=0;
static unsigned int g_r5_logical_pixels[NOVA_R5_MAX_LOGICAL_W * NOVA_R5_MAX_LOGICAL_H];
static unsigned int r5_select_scale(unsigned int phys_w,unsigned int phys_h) {
    /* Explicitly cap the transitional software path to exactly 4K UHD. */
    if(phys_w==3840U && phys_h==2160U) return 2U;
    return 1U;
}
static int r5_delta_to_logical(int physical,int *remainder) {
    if (g_r5_scale==1U) return physical;
    long value=(long)physical+(long)*remainder;
    int out=(int)(value/(long)g_r5_scale);
    *remainder=(int)(value%(long)g_r5_scale);
    return out;
}

