    nova_fd_puts((int)fd, "window_x="); nova_fd_put_u64((int)fd, g_scene.window_x < 0 ? 0UL : (unsigned long)g_scene.window_x); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "window_y="); nova_fd_put_u64((int)fd, g_scene.window_y < 0 ? 0UL : (unsigned long)g_scene.window_y); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "window_width="); nova_fd_put_u64((int)fd, g_scene.window_width); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "window_height="); nova_fd_put_u64((int)fd, g_scene.window_height); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "client_connected="); nova_fd_putln((int)fd, client_connection_count() ? "yes" : "no");
