        nova_fd_puts((int)fd, "client_slot"); nova_fd_put_u64((int)fd, ci+1U); nova_fd_puts((int)fd, "_generation="); nova_fd_put_u64((int)fd, (unsigned long)g_connections[ci].app_generation); nova_fd_putln((int)fd, "");
