    nova_fd_puts((int)fd, "client3_connected="); nova_fd_putln((int)fd,client_id_is_connected(3U)?"yes":"no");
    nova_fd_puts((int)fd, "client3_commits="); nova_fd_put_u64((int)fd,g_client_commits_by_id[3]);nova_fd_putln((int)fd,"");
    nova_fd_puts((int)fd, "client2_commits="); nova_fd_put_u64((int)fd, g_client_commits_by_id[2]); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "client_disconnects="); nova_fd_put_u64((int)fd, g_client.disconnects); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "client_surfaces_removed="); nova_fd_put_u64((int)fd, g_client.surfaces_removed); nova_fd_putln((int)fd, "");
    nova_fd_puts((int)fd, "client_buffers_created="); nova_fd_put_u64((int)fd, g_client.buffers_created); nova_fd_putln((int)fd, "");
