static unsigned int r3_unicode_index(const char **sp) {
    const unsigned char *s=(const unsigned char *)*sp;
    unsigned int v=(unsigned int)s[0];
    if (!v) return 0U;
    if (v<128U) { *sp=(const char *)(s+1); return (v>=32U && v<=126U)?(v-32U):31U; }
    unsigned int cp=0U, n=1U;
    if ((v&0xe0U)==0xc0U && s[1] && (s[1]&0xc0U)==0x80U) { cp=((v&31U)<<6)|(s[1]&63U);n=2U; }
    else if ((v&0xf0U)==0xe0U && s[1] && s[2] && (s[1]&0xc0U)==0x80U && (s[2]&0xc0U)==0x80U) { cp=((v&15U)<<12)|((s[1]&63U)<<6)|(s[2]&63U);n=3U; }
    *sp=(const char *)(s+n);
    /* Ç ç Ğ ğ İ ı Ö ö Ş ş Ü ü */
    static const unsigned int tr[12]={0xc7U,0xe7U,0x11eU,0x11fU,0x130U,0x131U,0xd6U,0xf6U,0x15eU,0x15fU,0xdcU,0xfcU};
    for(unsigned int i=0U;i<12U;i++) if(cp==tr[i]) return 95U+i;
    return (unsigned int)'?'-32U;
}
static void r19_legacy_text(unsigned char *base,unsigned int w,unsigned int h,unsigned int pitch,
                    int x,int y,int large,unsigned int color,const char *label,
                    int clip_x,int clip_y,unsigned int clip_w,unsigned int clip_h) {
    if (!base || !label || !clip_w || !clip_h) return;
    const unsigned char *bits=large?r3_large_bits:r3_small_bits;
    const struct r3_glyph *glyph=large?r3_large_glyph:r3_small_glyph;
    int cx0=clip_x>0?clip_x:0,cy0=clip_y>0?clip_y:0;
    int cx1=clip_x+(int)clip_w, cy1=clip_y+(int)clip_h;
    if (cx1>(int)w) cx1=(int)w;
    if (cy1>(int)h) cy1=(int)h;
    if(cx1<=cx0 || cy1<=cy0) return;
    int px=x; const char *pos=label;
    for(unsigned int q=0U;q<160U && *pos;q++) {
        unsigned int gi=r3_unicode_index(&pos);
        const struct r3_glyph *g=&glyph[gi];
        for(unsigned int yy=0U;yy<g->height;yy++) {
            int iy=y+(int)g->dy+(int)yy;
            if(iy<cy0 || iy>=cy1) continue;
            unsigned int *row=(unsigned int *)(base+(unsigned long)(unsigned int)iy*pitch);
            for(unsigned int xx=0U;xx<g->width;xx++) {
                int ix=px+(int)g->dx+(int)xx;
                if(ix<cx0 || ix>=cx1) continue;
                unsigned int idx=yy*(unsigned int)g->width+xx;
                unsigned char mask=bits[g->offset+idx/2U];
                unsigned int alpha=((idx&1U)?(mask&15U):(mask>>4))*17U;
                if(!alpha) continue;
                if(alpha==255U) row[(unsigned int)ix]=color&0x00ffffffU;
                else row[(unsigned int)ix]=nova_mix_rgb(row[(unsigned int)ix],color,alpha,255U);
            }
        }
        px+=(int)g->advance;
        if(px>cx1+44) break;
    }
}
static void r3_text(unsigned char*base,unsigned int w,unsigned int h,unsigned int p,int x,int y,int large,unsigned int color,const char*label,int cx,int cy,unsigned int cw,unsigned int ch){
 if(large>1){r19_legacy_text(base,w,h,p,x,y,large,color,label,cx,cy,cw,ch);return;}
 struct nova_ui_canvas canvas={base,w,h,p};unsigned int role=large?NOVA_UI_TITLE:NOVA_UI_BODY;
 nova_ui_text(canvas,x,y+nova_ui_face_for(role,1)->ascent,role,1,color,label,cx,cy,cw,ch);
}
static void r3_glass_rect(unsigned char *base,unsigned int w,unsigned int h,unsigned int p,
                          int x,int y,unsigned int rw,unsigned int rh,unsigned int radius,
                          unsigned int body,unsigned int edge) {
    nova_fill_soft_rect(base,w,h,p,x,y,rw,rh,radius,edge);
    if(rw>2U && rh>2U) nova_fill_soft_rect(base,w,h,p,x+1,y+1,rw-2U,rh-2U,radius?radius-1U:0U,body);
}
static void r3_dot(unsigned char *base,unsigned int w,unsigned int h,unsigned int p,
                   int x,int y,unsigned int dia,unsigned int color){
    nova_fill_soft_rect(base,w,h,p,x,y,dia,dia,dia/2U,color);
}

