/* R10 polished material raster: 1px coverage on circular corners.  Pure C.
 * The existing R9 shapes, protocol, surface model and protected paths remain intact. */
static void r18_alpha_round_excluding(unsigned char *b,unsigned int w,unsigned int h,unsigned int p,
                           int x,int y,unsigned int rw,unsigned int rh,unsigned int r,
                           unsigned int color,unsigned int alpha,int ex0,int ey0,int ex1,int ey1){
    if(!b||!rw||!rh||!alpha||p<w*4U)return;
    if(alpha>255U)alpha=255U;
    if(r>rw/2U)r=rw/2U;if(r>rh/2U)r=rh/2U;
    int xa=x<0?0:x,ya=y<0?0:y;
    int xb=x+(int)rw>(int)w?(int)w:x+(int)rw;
    int yb=y+(int)rh>(int)h?(int)h:y+(int)rh;
    if(xb<=xa||yb<=ya)return;
    for(int yy=ya;yy<yb;yy++){
        unsigned int *row=(unsigned int*)(b+(unsigned long)(unsigned int)yy*p);
        int dy=0,ty=yy-y;
        if(ty<(int)r)dy=(int)r-ty-1;
        else if(ty>=(int)rh-(int)r)dy=ty-((int)rh-(int)r);
        for(int xx=xa;xx<xb;xx++){
            /* Only skip pixels guaranteed to be overwritten by this opaque
             * XRGB client. Never skip another window or rounded boundary. */
            if(yy>=ey0&&yy<ey1&&xx>=ex0&&xx<ex1){xx=ex1-1;continue;}
            int dx=0,tx=xx-x;
            if(tx<(int)r)dx=(int)r-tx-1;
            else if(tx>=(int)rw-(int)r)dx=tx-((int)rw-(int)r);
            unsigned int a=alpha;
            if(dx||dy){
                unsigned int d2=(unsigned int)(dx*dx+dy*dy);
                unsigned int rr=r*r,spread=2U*r+1U;
                if(d2>=rr+spread)continue;
                if(d2>rr-spread && r>0U)
                    a=alpha*(rr+spread-d2)/(spread*2U);
                if(!a)continue;
            }
            row[(unsigned int)xx]=nova_mix_rgb(row[(unsigned int)xx],color,a,255U);
        }
    }
}
static void r8_alpha_round(unsigned char*b,unsigned int w,unsigned int h,unsigned int p,
 int x,int y,unsigned int rw,unsigned int rh,unsigned int r,unsigned int color,unsigned int alpha){
 r18_alpha_round_excluding(b,w,h,p,x,y,rw,rh,r,color,alpha,0,0,0,0);
}
/* Cached analytic shadow coverage, not a realtime blur. Single smooth falloff.
 * The table is immutable after local initialisation; no client controls its size. */
static unsigned char g_r19_shadow_alpha[36][36];
static int g_r19_shadow_ready;
static void r19_shadow(unsigned char*b,unsigned int w,unsigned int h,unsigned int pitch,int x,int y,unsigned int rw,unsigned int rh,unsigned int strength,int elide){
 if(!g_r19_shadow_ready){
  for(unsigned int j=0;j<36;j++){
   for(unsigned int i=0;i<36;i++){
   unsigned int square=i*i+j*j,root=0;while((root+1)*(root+1)<=square)root++;
   unsigned int d=root>12?root-12:0,remaining=d<22?22-d:0;
   g_r19_shadow_alpha[j][i]=(unsigned char)(remaining*remaining*255/(22*22));
   }
  }
  g_r19_shadow_ready=1;
 }
 int l=x-22,t=y-16,right=x+(int)rw+22,bottom=y+(int)rh+28;
 if(l<0)l=0;if(t<0)t=0;if(right>(int)w)right=(int)w;if(bottom>(int)h)bottom=(int)h;
 for(int yy=t;yy<bottom;yy++)for(int xx=l;xx<right;xx++){
  if(elide&&yy>=y+12&&yy<y+(int)rh-12&&xx>=x+12&&xx<x+(int)rw-12){xx=x+(int)rw-13;continue;}
  int dx=xx<x+12?x+12-xx:xx>x+(int)rw-13?xx-x-(int)rw+13:0;
  int dy=yy<y+18?y+18-yy:yy>y+(int)rh-7?yy-y-(int)rh+7:0;
  if(dx>=36||dy>=36)continue;unsigned int alpha=(unsigned int)g_r19_shadow_alpha[dy][dx]*strength/255U;
  if(alpha){unsigned int*pixel=(unsigned int*)(b+(unsigned long)(unsigned int)yy*pitch)+(unsigned int)xx;*pixel=nova_mix_rgb(*pixel,0x0007121b,alpha,255);}
 }
}
/* Soft atmospheric elevation with multiple broad, lightly opaque layers. */

static void r8_surface(unsigned char*b,unsigned int w,unsigned int h,unsigned int p,
                       int x,int y,unsigned int rw,unsigned int rh,unsigned int radius,
                       unsigned int body,unsigned int stroke){
    r8_alpha_round(b,w,h,p,x,y,rw,rh,radius,stroke,255U);
    if(rw>2U && rh>2U) r8_alpha_round(b,w,h,p,x+1,y+1,rw-2U,rh-2U,
                                       radius?radius-1U:0U,body,255U);
    if(rw>32U && rh>24U)
        r8_alpha_round(b,w,h,p,x+18,y+2,rw-36U,1U,0U,0x00eee0c6U,24U);
}
/* Paint a quiet metallic sweep, clipped inside any registered surface. */
static __attribute__((unused)) void r10_metal_sweep(unsigned char*b,unsigned int w,unsigned int h,unsigned int p,
    int x,int y,unsigned int rw,unsigned int rh,unsigned int lo,unsigned int hi){
    if(!rw||!rh)return;
    for(unsigned int yy=0U;yy<rh;yy++){
        unsigned int c=nova_mix_rgb(lo,hi,yy,rh);
        r8_alpha_round(b,w,h,p,x,y+(int)yy,rw,1U,0U,c,65U);
    }
}
static void r8_icon_grid(unsigned char*b,unsigned int w,unsigned int h,unsigned int p,
                         int x,int y,unsigned int color){
    for(int a=0;a<2;a++)for(int c=0;c<2;c++)
        nova_fill_soft_rect(b,w,h,p,x+c*13,y+a*13,10U,10U,3U,color);
}

/* NOVAOS R6 / HORIZON. All geometry derives from native C scene state.
 * These are software raster primitives, not HTML, SVG or a mock compositor. */

static __attribute__((unused)) void r6_surface(unsigned char *b,unsigned int w,unsigned int h,unsigned int p,
                      int x,int y,unsigned int rw,unsigned int rh,unsigned int fill) {
    r3_glass_rect(b,w,h,p,x,y,rw,rh,14U,fill,0x00dfe7f0U);
}
static void r6_glow_band(unsigned char *b,unsigned int w,unsigned int h,unsigned int p,
                         int cx,int cy,unsigned int rx,unsigned int ry,
                         unsigned int c1,unsigned int c2){
    nova_r2_glow(b,w,h,p,cx,cy,rx,ry,c1,c2);
}
static __attribute__((unused)) void r6_glow_clipped(unsigned char *base,unsigned int w,unsigned int h,unsigned int p,
                            int x,int y,unsigned int rw,unsigned int rh,
                            int center_x,int center_y,unsigned int rx,unsigned int ry,
                            unsigned int inner,unsigned int strength) {
    if(!base||!rx||!ry||!rw||!rh)return;
    int lo_x=x>0?x:0, lo_y=y>0?y:0;
    int hi_x=x+(int)rw<(int)w?x+(int)rw:(int)w;
    int hi_y=y+(int)rh<(int)h?y+(int)rh:(int)h;
    if(lo_x>=hi_x||lo_y>=hi_y)return;
    if(strength>255U)strength=255U;
    for(int py=lo_y;py<hi_y;py++){
        unsigned int dy=(unsigned int)(py>center_y?py-center_y:center_y-py);
        if(dy>=ry)continue;
        unsigned int span=rx*(ry-dy)/ry;
        if(!span)continue;
        unsigned int *row=(unsigned int*)(base+(unsigned long)(unsigned int)py*p);
        int start=center_x-(int)span>lo_x?center_x-(int)span:lo_x;
        int end=center_x+(int)span<hi_x?center_x+(int)span:hi_x;
        for(int px=start;px<end;px++){
            unsigned int dx=(unsigned int)(px>center_x?px-center_x:center_x-px);
            unsigned int alpha=strength*(ry-dy)/ry*(span-dx)/span;
            if(alpha)row[(unsigned int)px]=nova_mix_rgb(row[(unsigned int)px],inner,alpha,255U);
        }
    }
}
/* HORIZON R7 / LUMINA.  Replaces the demo-status composition with a
 * task-backed launcher, compositor-owned appearance control, distinct
 * independent floating surfaces and an original raster wallpaper.  All
 * hit regions used below are shared with the input path. */

/* R12 / LUMINA ASSETS: compiled RGB565 landscape; bounded XRGB8888 blit.
 * No guest filesystem decoder, network access or new privilege required. */
static struct nova_wallpaper_cache g_wallpaper_cache;
#ifdef NOVA_RENDER_TEST_REFERENCE
static int g_test_reference_wallpaper;
#endif
static void r12_wallpaper(unsigned char*b,unsigned int w,unsigned int h,unsigned int p){
    if (!b || w<400U || h<300U || p<w*4U)return;
    int use_cache=NOVA_R24_OPTIMIZED;
#ifdef NOVA_RENDER_TEST_REFERENCE
    if(g_test_reference_wallpaper)use_cache=0;
#endif
    if(use_cache){
     int cached=nova_wallpaper_cached(&g_wallpaper_cache,nova_r12_wall_rgb565,sizeof(nova_r12_wall_rgb565),NOVA_R12_WALL_W,NOVA_R12_WALL_H,b,w,h,p);
     if(!cached)g_wallpaper_cache.fallbacks++;
     g_r24.wallpaper_frames=g_wallpaper_cache.frames;g_r24.wallpaper_palette_builds=g_wallpaper_cache.palette_builds;g_r24.wallpaper_map_builds=g_wallpaper_cache.map_builds;g_r24.wallpaper_fallbacks=g_wallpaper_cache.fallbacks;g_r24.wallpaper_cache_bytes=sizeof(g_wallpaper_cache);
     if(cached)return;
    }
    for(unsigned int y=0;y<h;y++){
        unsigned int*row=(unsigned int*)(b+(unsigned long)y*p);
        unsigned int sy=(unsigned int)((unsigned long long)y*NOVA_R12_WALL_H/h);
        for(unsigned int x=0;x<w;x++){
            unsigned int sx=(unsigned int)((unsigned long long)x*NOVA_R12_WALL_W/w);
            unsigned long j=((unsigned long)sy*NOVA_R12_WALL_W+sx)*2UL;
            unsigned int raw=(unsigned int)nova_r12_wall_rgb565[j]|((unsigned int)nova_r12_wall_rgb565[j+1UL]<<8);
            unsigned int r=((raw>>11)&31U)*255U/31U;
            unsigned int g=((raw>>5)&63U)*255U/63U;
            unsigned int bl=(raw&31U)*255U/31U;
            unsigned int c=(r<<16)|(g<<8)|bl;
            row[x]=nova_mix_rgb(c,0x00080709U,40U,255U);
        }
    }
}
/* High fidelity Lucide-source icon rasters, recognized by known system/demo IDs only. */
static void r12_icon(unsigned char*b,unsigned int w,unsigned int h,unsigned int p,
                     int x,int y,unsigned int size,unsigned int id){
    if(!b || !size || size>96U || p<w*4U)return;
    const unsigned char*mask=id==0U?nova_r12_icon_library:
      id==1U?nova_r12_icon_controls:id==2U?nova_r12_icon_demo_a:nova_r12_icon_demo_b;
    for(unsigned int yy=0;yy<size;yy++){
        int py=y+(int)yy;if(py<0||py>=(int)h)continue;
        unsigned int*row=(unsigned int*)(b+(unsigned long)(unsigned int)py*p);
        unsigned int fy=yy*47U*256U/(size>1U?size-1U:1U),srcy=fy>>8,wy=fy&255U;
        for(unsigned int xx=0;xx<size;xx++){
            int px=x+(int)xx;if(px<0||px>=(int)w)continue;
            unsigned int fx=xx*47U*256U/(size>1U?size-1U:1U),sx=fx>>8,wx=fx&255U;
            unsigned int nx=sx<47U?sx+1U:sx,ny=srcy<47U?srcy+1U:srcy;
            unsigned int a=mask[srcy*48U+sx]*(256U-wx)+mask[srcy*48U+nx]*wx;
            unsigned int z=mask[ny*48U+sx]*(256U-wx)+mask[ny*48U+nx]*wx;
            unsigned int alpha=(a*(256U-wy)+z*wy+32768U)>>16;
            if(alpha)row[(unsigned int)px]=nova_mix_rgb(row[(unsigned int)px],0x00f5e5c8U,alpha,255U);
        }
    }
}
static int r12_known_demo_icon(const struct nova_desktop_task_entry*entry){
    if(!entry)return -1;
    const char*s=entry->display_name;
    if (s[0]=='N'&&s[1]=='o'&&s[2]=='v'&&s[3]=='a'&&s[4]==' '&&
        s[5]=='D'&&s[6]=='e'&&s[7]=='m'&&s[8]=='o'&&s[9]==' '&&
        (s[10]=='A'||s[10]=='B')&&s[11]=='\0')return s[10]=='A'?2:3;
    return -1;
}

/* R11 / CALM: quiet, textured graphite atmosphere. No hard stripes or slabs. */
static void r7_wallpaper_wave(unsigned char *base,unsigned int w,unsigned int h,unsigned int p){
    const struct r8_palette*t=r8_colors();
    if(w<400U||h<300U)return;
    unsigned int top=g_render.theme?0x001b2026U:0x000e1118U;
    unsigned int bottom=g_render.theme?0x0032383cU:0x0023272eU;
    for(unsigned int y=0U;y<h;y++){
        unsigned int c=nova_mix_rgb(top,bottom,y,h);
        fill_rect(base,w,h,p,0,(int)y,w,1U,c);
    }
    /* Two broad pools of reflected ambient light, deliberately low saturation. */
    r6_glow_band(base,w,h,p,(int)(w*76U/100U),(int)(h*87U/100U),
                 w*58U/100U,h*45U/100U,g_render.theme?0x00545e63U:0x004a403bU,bottom);
    r6_glow_band(base,w,h,p,(int)(w*19U/100U),(int)(h*105U/100U),
                 w*60U/100U,h*42U/100U,g_render.theme?0x003c444aU:0x00302d2bU,top);
    /* Fine horizon light rather than a decorative grid. */
    if(h>180U)r8_alpha_round(base,w,h,p,(int)(w/4U),(int)(h*82U/100U),w/2U,1U,0U,t->accent,15U);
}
static void r3_background(unsigned char *base,unsigned int w,unsigned int h,unsigned int p,unsigned int theme){
    (void)theme;
    if((g_render.theme&1U)==0U) r12_wallpaper(base,w,h,p);
    else r7_wallpaper_wave(base,w,h,p);
}

