static void r24_ms(unsigned long long ns,char*out){char whole[32];r23_number(ns/1000000ULL,whole);unsigned int n=0;while(whole[n]){out[n]=whole[n];n++;}out[n++]='.';unsigned int fraction=(unsigned int)(ns/1000ULL%1000ULL);out[n++]=(char)('0'+fraction/100);out[n++]=(char)('0'+fraction/10%10);out[n++]=(char)('0'+fraction%10);out[n++]=' ';out[n++]='m';out[n++]='s';out[n]=0;}
