static void r24_cursor_capture(struct nova_scanout_buffer*buf,unsigned char*base,unsigned int w,unsigned int h,unsigned int pitch,int restore){
 if(!buf||!base)return;int x=restore?buf->r24_x:g_render.cursor_x,y=restore?buf->r24_y:g_render.cursor_y;
 for(unsigned int yy=0;yy<20;yy++)for(unsigned int xx=0;xx<12;xx++){int px=x+(int)xx,py=y+(int)yy;if(px<0||py<0||(unsigned int)px>=w||(unsigned int)py>=h)continue;unsigned int*pixel=(unsigned int*)(base+(unsigned long)py*pitch)+(unsigned int)px;if(restore)*pixel=buf->r24_under[yy*12+xx];else buf->r24_under[yy*12+xx]=*pixel;}
 if(!restore){buf->r24_x=x;buf->r24_y=y;buf->r24_valid=1;}
}
static void r3_cursor(unsigned char *base,unsigned int w,unsigned int h,unsigned int p){
    if(g_r24_capture)r24_cursor_capture(g_r24_capture,base,w,h,p,0);
    /* Compact OS-style arrow; pointer coordinates and event routing unchanged. */
    int x=g_render.cursor_x,y=g_render.cursor_y;
    for(unsigned int yy=0U;yy<18U;yy++){
        unsigned int len=yy<13U?yy/2U+2U:(18U-yy)/2U+2U;
        fill_rect(base,w,h,p,x,y+(int)yy,len+2U,1U,0x00131d2eU);
        if(len>1U) fill_rect(base,w,h,p,x+1,y+(int)yy,len,1U,0x00fcfdffU);
    }
}

static __attribute__((unused)) void nova_r2_background(unsigned char *base,unsigned int w,unsigned int h,unsigned int p,unsigned int theme) {
    /* Gradient is created with existing safe scanline primitives. */
    nova_draw_wallpaper(base,w,h,p,theme);
    if (w<320U || h<240U) return;
    nova_r2_glow(base,w,h,p,(int)(w*78U/100U),(int)(h*36U/100U),w/4U,h/3U,
                 0x00234465U,0x001c3249U);
    nova_r2_glow(base,w,h,p,(int)(w*8U/100U),(int)(h*87U/100U),w/4U,h/5U,
                 0x00254367U,0x001b314bU);
    /* Restrained ambient star marks, not fake interactive controls. */
    for (unsigned int i=0U;i<8U;i++) {
        unsigned int xx=(w*(17U+i*9U))/100U;
        unsigned int yy=(h*(28U+(i*13U)%49U))/100U;
        if (xx<w && yy<h && (xx<120U || yy>100U))
            fill_rect(base,w,h,p,(int)xx,(int)yy,2U,2U,0x00435e75U);
    }
}

static __attribute__((unused)) void nova_r2_panel(unsigned char *base,unsigned int w,unsigned int h,unsigned int p,
                          unsigned int height) {
    if (!height || height>h) return;
    fill_rect(base,w,h,p,0,0,w,height,0x00131d2bU);
    fill_rect(base,w,h,p,0,(int)height-1,w,1U,0x00374457U);
    /* Subtle identity mark, fixed to the existing topbar non-task region. */
    nova_fill_soft_rect(base,w,h,p,18,15,30U,30U,9U,0x00458ad7U);
    nova_fill_soft_rect(base,w,h,p,24,21,18U,18U,5U,0x00192843U);
    fill_rect(base,w,h,p,30,24,6U,12U,0x009bdfffU);
    nova_r2_text(base,w,h,p,58,21,2U,0x00f2f6fdU,"NOVAOS",0,0,210U,height);
    nova_r2_text(base,w,h,p,58,43,1U,0x0093a6bbU,"DESKTOP",0,0,210U,height);
    if (w>1160U && g_desktop_tasks.count<5U) {
        nova_fill_soft_rect(base,w,h,p,(int)w-164,15,146U,32U,13U,0x00212f40U);
        fill_rect(base,w,h,p,(int)w-151,29,5U,5U,0x006bd5baU);
        nova_r2_text(base,w,h,p,(int)w-139,27,1U,0x00cddae8U,"DESKTOP PREVIEW",
                     (int)w-164,15,146U,32U);
    }
}

static void clamp_client_surface(struct nova_client_surface *s, unsigned int width, unsigned int height) {
    if (!s) return;
    if (s->pending_width < 96U) s->pending_width = 96U;
    if (s->pending_height < 72U) s->pending_height = 72U;
    if (s->pending_width > width) s->pending_width = width;
    if (s->pending_height > height) s->pending_height = height;
    int max_x = width > s->pending_width ? (int)(width - s->pending_width) : 0;
    int max_y = height > s->pending_height ? (int)(height - s->pending_height) : 0;
    if (s->pending_x < 0) s->pending_x = 0;
    if (s->pending_y < (int)g_scene.panel_height) s->pending_y = (int)g_scene.panel_height;
    if (s->pending_x > max_x) s->pending_x = max_x;
    if(max_y<(int)g_scene.panel_height)max_y=(int)g_scene.panel_height;
    if (s->pending_y > max_y) s->pending_y = max_y;
}

static unsigned int top_client_surface_at(int x, int y) {
    unsigned int best_id=0U, best_z=0U;
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) {
        struct nova_client_surface *s=&g_surfaces[i];
        if (!s->used || !s->committed || s->minimized) continue;
        if (x<s->x || y<s->y || x>=s->x+(int)s->width || y>=s->y+(int)s->height) continue;
        if (!best_id || s->z_index>=best_z) { best_id=s->surface_id; best_z=s->z_index; }
    }
    return best_id;
}

static unsigned int first_client_surface_by_z(void) {
    unsigned int id=0U, best=0xffffffffU;
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) {
        struct nova_client_surface *s=&g_surfaces[i];
        if (s->used && s->committed && !s->minimized && s->z_index<best) { best=s->z_index; id=s->surface_id; }
    }
    return id;
}

static unsigned int next_client_surface_by_z(unsigned int current_id) {
    struct nova_client_surface *cur=find_client_surface(current_id);
    if (!cur || !cur->committed) return first_client_surface_by_z();
    unsigned int id=0U, best=0xffffffffU;
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) {
        struct nova_client_surface *s=&g_surfaces[i];
        if (s->used && s->committed && !s->minimized && s->z_index>cur->z_index && s->z_index<best) { best=s->z_index; id=s->surface_id; }
    }
    return id;
}

static int send_client_event(unsigned int type, unsigned int surface_id, unsigned int code, int value,
                             unsigned int configure_serial, int x, int y, unsigned int width, unsigned int height) {
    struct nova_client_surface *surface=find_client_surface(surface_id);
    if (!surface || surface->owner_fd<0 || !surface_id) return 0;
    struct nova_client_connection *conn=connection_for_fd(surface->owner_fd);
    if (!conn || !conn->used || !conn->authenticated || conn->client_id!=surface->client_id) return 0;
    if(surface->minimized && (type==NOVA_SURFACE_EVENT_KEY||type==NOVA_SURFACE_EVENT_POINTER))return 0;
    if(type==NOVA_SURFACE_EVENT_KEY){
        if(code==NOVA_KEY_TAB){
            if(!connection_has_capability(conn,NOVA_APP_CAP_INPUT_TAB_CAPTURE)){
                log_capability_denial(NOVA_APP_CAP_TOKEN_INPUT_TAB_CAPTURE,&g_client.tab_capture_denials);
                return 0;
            }
        } else if(!connection_has_capability(conn,NOVA_APP_CAP_INPUT_TEXT)){
            log_capability_denial(NOVA_APP_CAP_TOKEN_INPUT_TEXT,&g_client.input_text_denials);
            return 0;
        }
    }
    struct nova_surface_event ev;
    nova_zero(&ev,sizeof(ev));
    ev.magic=NOVA_SURFACE_PROTOCOL_MAGIC; ev.version=NOVA_SURFACE_PROTOCOL_VERSION;
    ev.type=type; ev.size=sizeof(ev); ev.client_id=surface->client_id; ev.surface_id=surface_id;
    ev.code=code; ev.value=value; ev.sequence=(unsigned int)(g_client.events_routed+1UL);
    ev.modifiers=g_input_modifiers;
    ev.cursor_x=g_render.cursor_x; ev.cursor_y=g_render.cursor_y;
    ev.configure_serial=configure_serial; ev.x=x; ev.y=y; ev.width=width; ev.height=height;
    long n=nova_write(surface->owner_fd,&ev,sizeof(ev));
    if ((unsigned long)n!=sizeof(ev)) {if(n==-NOVA_EAGAIN)g_r24.event_backpressure++;else g_r24.event_errors++;return 0;}
    g_client.events_routed++;
    return 1;
}

static char g_r57_open_name[NOVA_SURFACE_CLIPBOARD_BYTES];
static unsigned long long g_r57_open_deadline;
static int r57_open_pending(const struct nova_client_connection*c){
 return g_r57_open_name[0]&&c&&c->used&&c->authenticated&&c->client_id==3&&c->desktop_open_subscribed&&nova_streq(c->app_id,"nova.files")&&connection_has_capability(c,NOVA_APP_CAP_UI_SURFACE);
}
static int r57_open_ready(const struct nova_client_connection*c){
 if(!r57_open_pending(c))return 0;
 struct nova_client_surface*s=find_client_surface(300);
 return s&&s->committed&&s->owner_fd==c->fd&&s->client_id==3;
}
static void r57_flush_open(struct nova_client_connection*c){
 if(!g_r57_open_name[0])return;
 if(nova_render_clock(1)>g_r57_open_deadline){g_r57_open_name[0]=0;return;}
 if(!r57_open_pending(c))return;
 struct nova_client_surface*s=find_client_surface(300);if(!s||!s->committed||s->owner_fd!=c->fd||s->client_id!=3)return;
 struct nova_surface_event ev;nova_zero(&ev,sizeof ev);ev.magic=NOVA_SURFACE_PROTOCOL_MAGIC;ev.version=6;ev.size=sizeof ev;ev.type=NOVA_SURFACE_EVENT_DESKTOP_OPEN;ev.client_id=3;ev.surface_id=300;ev.sequence=(unsigned)(g_client.events_routed+1UL);ev.clipboard_length=nova_desktop_open_name(g_r57_open_name);nova_copy(ev.clipboard,g_r57_open_name,ev.clipboard_length+1);
 if(!nova_desktop_open_event(&ev)){g_r57_open_name[0]=0;return;}
 struct nova_iovec iov={&ev,sizeof ev};struct nova_msghdr msg;nova_zero(&msg,sizeof msg);msg.msg_iov=&iov;msg.msg_iovlen=1;
 if(nova_sendmsg(c->fd,&msg,NOVA_MSG_NOSIGNAL|NOVA_MSG_DONTWAIT)==(long)sizeof ev){g_client.events_routed++;g_r57_open_name[0]=0;}
}
static unsigned int r21_theme_surface(const struct nova_client_connection*c){
 if(!c||!c->used||!c->authenticated||!c->theme_subscribed)return 0;
 for(unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++)if(g_surfaces[i].used&&g_surfaces[i].owner_fd==c->fd&&g_surfaces[i].client_id==c->client_id)return g_surfaces[i].surface_id;return 0;
}
static void r21_flush_theme(struct nova_client_connection*c){
 r57_flush_open(c);
 unsigned int surface=r21_theme_surface(c);if(!surface||c->theme_sent==g_session_theme.generation)return;
 struct nova_surface_event e;nova_zero(&e,sizeof(e));e.magic=NOVA_SURFACE_PROTOCOL_MAGIC;e.version=6;e.size=sizeof(e);e.type=NOVA_SURFACE_EVENT_THEME;e.client_id=c->client_id;e.surface_id=surface;e.code=g_session_theme.choice;e.value=(int)g_session_theme.generation;
 struct nova_iovec iov={&e,sizeof(e)};struct nova_msghdr msg;nova_zero(&msg,sizeof(msg));msg.msg_iov=&iov;msg.msg_iovlen=1;
 if(nova_sendmsg(c->fd,&msg,NOVA_MSG_NOSIGNAL|NOVA_MSG_DONTWAIT)==(long)sizeof(e))c->theme_sent=g_session_theme.generation;
}
static int r21_set_theme(unsigned int choice){
 if(choice>2U||g_session_theme.generation>=0x7fffffffU)return 0;/* Explicit reapply also ends a client-local preview; clients avoid identical repaint. */
 g_session_theme.choice=choice;g_session_theme.generation++;g_scene.visual_generation++;
 for(unsigned int i=0;i<NOVA_MAX_CLIENT_CONNECTIONS;i++)r21_flush_theme(&g_connections[i]);
 nova_puts("[nova-compositor] session_theme=");nova_put_u64(choice);nova_puts(" generation=");nova_put_u64(g_session_theme.generation);nova_putln(" persistent=no");return 1;
}
static int route_client_event(unsigned int type, unsigned int surface_id, unsigned int code, int value) {
    return send_client_event(type,surface_id,code,value,0U,0,0,0U,0U);
}

static int clipboard_payload_valid(const struct nova_surface_message *m) {
    if (!m || m->clipboard_length>=NOVA_SURFACE_CLIPBOARD_BYTES) return 0;
    for (unsigned int i=0;i<m->clipboard_length;i++) {
        unsigned char c=(unsigned char)m->clipboard[i];
        if (c<0x20U || c>0x7eU) return 0;
    }
    return 1;
}

static int client_clipboard_allowed(const struct nova_client_surface *s) {
    return s && s->committed && s->surface_id==g_client.focus_surface &&
           (s->input_flags&NOVA_SURFACE_INPUT_CLIPBOARD);
}

static void clear_client_clipboard(const char *reason) {
    if (!g_clipboard.length && !g_clipboard.owner_client_id && !g_clipboard.owner_surface_id) return;
    nova_zero(g_clipboard.bytes,sizeof(g_clipboard.bytes)); g_clipboard.length=0U;
    g_clipboard.owner_client_id=0U; g_clipboard.owner_surface_id=0U; g_clipboard.clears++;
    nova_puts("[nova-compositor] clipboard=CLEARED reason="); nova_putln(reason?reason:"unknown");
}

static int set_client_clipboard(const struct nova_client_surface *s, const struct nova_surface_message *m) {
    if (!surface_has_capability(s,NOVA_APP_CAP_CLIPBOARD_WRITE)) {
        log_capability_denial(NOVA_APP_CAP_TOKEN_CLIPBOARD_WRITE,&g_client.clipboard_write_denials);
        return 1;
    }
    if (!client_clipboard_allowed(s)) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=clipboard_surface_not_focused"); return 1; }
    if (!clipboard_payload_valid(m)) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=clipboard_payload_invalid"); return 1; }
    nova_zero(g_clipboard.bytes,sizeof(g_clipboard.bytes));
    for (unsigned int i=0;i<m->clipboard_length;i++) g_clipboard.bytes[i]=m->clipboard[i];
    g_clipboard.length=m->clipboard_length; g_clipboard.owner_client_id=m->client_id; g_clipboard.owner_surface_id=m->surface_id;
    g_clipboard.sets++;
    nova_puts("[nova-compositor] clipboard=SET length="); nova_put_u64(g_clipboard.length); nova_putln("");
    return 1;
}

static int send_clipboard_event(const struct nova_client_surface *s) {
    if (!surface_has_capability(s,NOVA_APP_CAP_CLIPBOARD_READ)) return 0;
    if (!client_clipboard_allowed(s) || !s || s->owner_fd<0) return 0;
    struct nova_client_connection *conn=connection_for_fd(s->owner_fd);
    if (!conn || !conn->used || conn->client_id!=s->client_id) return 0;
    struct nova_surface_event ev; nova_zero(&ev,sizeof(ev));
    ev.magic=NOVA_SURFACE_PROTOCOL_MAGIC; ev.version=NOVA_SURFACE_PROTOCOL_VERSION;
    ev.type=NOVA_SURFACE_EVENT_CLIPBOARD; ev.size=sizeof(ev); ev.client_id=s->client_id; ev.surface_id=s->surface_id;
    ev.sequence=(unsigned int)(g_client.events_routed+1UL); ev.modifiers=g_input_modifiers;
    ev.clipboard_length=g_clipboard.length;
    for (unsigned int i=0;i<g_clipboard.length;i++) ev.clipboard[i]=g_clipboard.bytes[i];
    long n=nova_write(s->owner_fd,&ev,sizeof(ev)); if ((unsigned long)n!=sizeof(ev)) return 0;
    g_client.events_routed++; g_clipboard.gets++;
    nova_puts("[nova-compositor] clipboard=GET length="); nova_put_u64(g_clipboard.length); nova_putln("");
    return 1;
}

static int get_client_clipboard(const struct nova_client_surface *s) {
    if (!surface_has_capability(s,NOVA_APP_CAP_CLIPBOARD_READ)) {
        log_capability_denial(NOVA_APP_CAP_TOKEN_CLIPBOARD_READ,&g_client.clipboard_read_denials);
        return 1;
    }
    if (!client_clipboard_allowed(s)) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=clipboard_surface_not_focused"); return 1; }
    if (!send_clipboard_event(s)) { nova_putln("[nova-compositor] clipboard=GET_FAILED"); return 0; }
    return 1;
}

static unsigned int modifier_mask_for_key(unsigned int code) {
    if (code==NOVA_KEY_LEFTSHIFT || code==NOVA_KEY_RIGHTSHIFT) return NOVA_INPUT_MOD_SHIFT;
    if (code==NOVA_KEY_LEFTCTRL || code==NOVA_KEY_RIGHTCTRL) return NOVA_INPUT_MOD_CTRL;
    return 0U;
}

static void raise_client_surface(struct nova_client_surface *s) {
    if (!s || !s->committed) return;
    unsigned int top=max_client_z();
    if (s->z_index>=top) return;
    s->z_index=top<0xfffffffeU?top+1U:top;
    s->pending_z_index=s->z_index;
    g_client.window_raises++; g_client.surface_generation++; g_scene.visual_generation++;
    nova_puts("[nova-compositor] toplevel_raise="); nova_put_u64(s->surface_id); nova_puts(" z="); nova_put_u64(s->z_index); nova_putln("");
}

static int send_surface_configure(struct nova_client_surface *s, unsigned int width, unsigned int height) {
    if (!s || !s->committed || s->role!=NOVA_SURFACE_ROLE_TOPLEVEL) return 0;
    if (width<s->min_width) width=s->min_width; if (height<s->min_height) height=s->min_height;
    if (width>s->max_width) width=s->max_width; if (height>s->max_height) height=s->max_height;
    if (!width || !height) return 0;
    unsigned int serial=++g_client.next_configure_serial;
    if (!serial) serial=++g_client.next_configure_serial;
    s->configure_serial=serial; s->acked_configure_serial=0U;
    s->configure_width=width; s->configure_height=height; s->awaiting_configure=1;
    if (!send_client_event(NOVA_SURFACE_EVENT_CONFIGURE,s->surface_id,0U,0,serial,s->x,s->y,width,height)) {
        s->awaiting_configure=0; return 0;
    }
    g_client.configures_sent++;
    nova_puts("[nova-compositor] toplevel_configure="); nova_put_u64(s->surface_id);
    nova_puts(" serial="); nova_put_u64(serial); nova_puts(" width="); nova_put_u64(width);
    nova_puts(" height="); nova_put_u64(height); nova_putln("");
    return 1;
}

static int send_close_request(struct nova_client_surface *s) {
    if (!s || !s->committed || s->role!=NOVA_SURFACE_ROLE_TOPLEVEL) return 0;
    if (!send_client_event(NOVA_SURFACE_EVENT_CLOSE_REQUEST,s->surface_id,0U,0,0U,s->x,s->y,s->width,s->height)) return 0;
    g_client.close_requests++;
    nova_puts("[nova-compositor] toplevel_close_request="); nova_put_u64(s->surface_id); nova_putln("");
    return 1;
}

static void set_client_focus(unsigned int surface_id) {
    g_launch_focus_client=0; /* Any intervening focus choice cancels a pending launch. */
    if(surface_id){struct nova_client_surface *target=find_client_surface(surface_id);if(!target||!target->used||!target->committed)return;}
    if(surface_id)g_terminal.focused=0;
    unsigned int old=g_client.focus_surface;
    if (old==surface_id) {
        struct nova_client_surface *same=find_client_surface(surface_id); if (same) raise_client_surface(same);
        return;
    }
    if (old) (void)route_client_event(NOVA_SURFACE_EVENT_FOCUS,old,0U,0);
    g_client.focus_surface=surface_id;
    if (surface_id) {
        struct nova_client_surface *s=find_client_surface(surface_id); if (s) {s->minimized=0;raise_client_surface(s);}
        (void)route_client_event(NOVA_SURFACE_EVENT_FOCUS,surface_id,0U,1);
    }
    g_scene.visual_generation++;
}

/* Only a successful trusted desktop launch intent may focus a new map.
 * An application commit alone never obtains this authority. */
static void r48_focus_new_surface(struct nova_client_surface*s){
 if(!g_launch_focus_client)return;
 if(nova_render_clock(1)>g_launch_focus_deadline){g_launch_focus_client=0;return;}
 if(s&&s->committed&&s->client_id==g_launch_focus_client)set_client_focus(s->surface_id);
}

static void r25_terminal_focus(void){
    set_client_focus(0);g_terminal.focused=1;
    unsigned top=max_client_z();g_terminal.z_index=top<0xfffffffeU?top+1U:top;
    g_scene.visual_generation++;
}

static void cycle_focus(void) {
    if (!client_surface_count()) {
        g_scene.focus_index=g_scene.focus_index?0U:1U;
        return;
    }
    if (g_client.focus_surface) {
        unsigned int next=next_client_surface_by_z(g_client.focus_surface);
        set_client_focus(next);
        if (!next) g_scene.focus_index=0U;
    } else if (g_scene.focus_index==1U) {
        g_scene.focus_index=0U;
        set_client_focus(first_client_surface_by_z());
    } else {
        g_scene.focus_index=1U;
    }
}

static unsigned int g_r17_alt_keys;
static unsigned long g_r17_minimizes,g_r17_maximizes,g_r17_switches;
static int r17_minimize(struct nova_client_surface *s){
    if(!s||!s->used||!s->committed||s->minimized)return 0;
    s->minimized=1;
    if(g_client_grab.surface_id==s->surface_id)clear_client_grab();
    if(g_files_path_drop.surface==s->surface_id)nova_path_drop_cancel(&g_files_path_drop);if(g_client.pointer_surface==s->surface_id)g_client.pointer_surface=0;
    if(g_client.focus_surface==s->surface_id)set_client_focus(first_client_surface_by_z());
    g_r17_minimizes++;g_scene.visual_generation++;return 1;
}
static int r17_toggle_maximize(struct nova_client_surface *s,unsigned int w,unsigned int h){
    if(!s||!s->used||!s->committed||s->minimized||s->awaiting_configure||
       h<=g_scene.panel_height+116U||w<160U)return 0;
    if(s->max_width==s->min_width&&s->max_height==s->min_height)return 0;
    int old_x=s->x,old_y=s->y;
    unsigned int target_w,target_h;
    if(!s->maximized){
        s->restore_x=s->x;s->restore_y=s->y;s->restore_width=s->width;s->restore_height=s->height;
        target_w=w-16U;target_h=h-g_scene.panel_height-116U;
        s->x=s->pending_x=8;s->y=s->pending_y=(int)g_scene.panel_height+8;
    }else{
        target_w=s->restore_width;target_h=s->restore_height;
        s->x=s->pending_x=s->restore_x;s->y=s->pending_y=s->restore_y;
    }
    if(!send_surface_configure(s,target_w,target_h)){
        s->x=s->pending_x=old_x;s->y=s->pending_y=old_y;return 0;
    }
    s->maximized^=1U;g_r17_maximizes++;g_scene.visual_generation++;return 1;
}
static int r17_switch_window(void){
    /* Trusted terminal is a WM participant, not a fourth authenticated client. */
    if(g_terminal.visible&&g_terminal.focused){
        g_terminal.focused=0;g_terminal.grab=0;
        for(unsigned i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++)
            if(g_surfaces[i].used&&g_surfaces[i].committed){set_client_focus(g_surfaces[i].surface_id);return 1;}
        g_terminal.focused=1;return 1;
    }

    unsigned int current=NOVA_SURFACE_MAX_CLIENT_SURFACES;
    for(unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++)
        if(g_surfaces[i].used&&g_surfaces[i].surface_id==g_client.focus_surface){current=i;break;}
    for(unsigned int step=1;step<=NOVA_SURFACE_MAX_CLIENT_SURFACES;step++){
        unsigned int i=(current+step)%NOVA_SURFACE_MAX_CLIENT_SURFACES;
        if(g_terminal.visible && current<NOVA_SURFACE_MAX_CLIENT_SURFACES && i<=current){
            r25_terminal_focus();return 1;
        }
        if(g_surfaces[i].used&&g_surfaces[i].committed){
            g_surfaces[i].minimized=0;set_client_focus(g_surfaces[i].surface_id);
            g_r17_switches++;return 1;
        }
    }
    return 0;
}
static int r17_shortcut(unsigned int code,unsigned int w,unsigned int h){
    if(!g_r17_alt_keys)return 0;
    struct nova_client_surface *s=find_client_surface(g_client.focus_surface);
    if(code==NOVA_KEY_TAB){(void)r17_switch_window();return 1;}
    if(code==62U){if(s)(void)send_close_request(s);return 1;} /* Alt-F4 */
    if(code==NOVA_KEY_M){(void)r17_minimize(s);return 1;}
    if(code==68U){(void)r17_toggle_maximize(s,w,h);return 1;} /* Alt-F10 */
    return 0;
}

static void desktop_addr(struct nova_sockaddr_un *addr) {
    const char path[] = NOVA_DESKTOP_SOCKET_PATH;
    nova_zero(addr,sizeof(*addr)); addr->sun_family=NOVA_AF_UNIX;
    for (unsigned long i=0;i<sizeof(path)&&i<sizeof(addr->sun_path);i++) addr->sun_path[i]=path[i];
}

static int setup_desktop_listener(void) {
    struct nova_sockaddr_un addr; desktop_addr(&addr);
    (void)nova_unlink(NOVA_DESKTOP_SOCKET_PATH);
    long fd=nova_socket(NOVA_AF_UNIX,NOVA_SOCK_SEQPACKET|NOVA_SOCK_NONBLOCK,0);
    if (fd<0) { nova_putln("[nova-compositor] desktop_control=WAITING reason=socket_failed"); return -1; }
    long rc=nova_bind((int)fd,&addr,sizeof(addr));
    if (rc<0) { nova_putln("[nova-compositor] desktop_control=WAITING reason=bind_failed"); (void)nova_close((int)fd); return -1; }
    rc=nova_listen((int)fd,2);
    if (rc<0) { nova_putln("[nova-compositor] desktop_control=WAITING reason=listen_failed"); (void)nova_close((int)fd); return -1; }
    nova_putln("[nova-compositor] desktop_control=LISTENING protocol=1");
    return (int)fd;
}

static int accept_desktop_client(int listener, int old_client) {
    long client=nova_accept4(listener,NOVA_SOCK_NONBLOCK);
    if (client<0) return old_client;
    if (old_client>=0) (void)nova_close(old_client);
    g_desktop_fd=(int)client; g_desktop.connected=1; g_desktop.protocol_version=NOVA_DESKTOP_PROTOCOL_VERSION;
    return (int)client;
}

static void disconnect_desktop_client(int *client) {
    if (*client>=0) (void)nova_close(*client);
    *client=-1; g_desktop_fd=-1;
    g_desktop_tasks.staging=0; g_desktop_tasks.staging_count=0U; g_desktop_tasks.staging_expected=0U;
    if (g_desktop.connected) {
        g_desktop.connected=0; g_desktop.disconnects++;
        nova_putln("[nova-compositor] desktop_control=DISCONNECTED policy_retained=yes task-model-retained=yes");
    }
}

static int desktop_task_name_valid(const char name[NOVA_DESKTOP_TASK_NAME_BYTES]) {
    if (!name || !name[0]) return 0;
    for (unsigned int i=0U; i<NOVA_DESKTOP_TASK_NAME_BYTES; i++) {
        unsigned char c=(unsigned char)name[i];
        if (c=='\0') return i!=0U;
        if (c<0x20U || c>0x7eU || c=='/' || c=='\\') return 0;
    }
    return 0;
}

static struct nova_desktop_task_entry *desktop_task_for_client(unsigned int client_id) {
    if (!client_id) return (struct nova_desktop_task_entry *)0;
    for (unsigned int i=0U; i<g_desktop_tasks.count; i++)
        if (g_desktop_tasks.entries[i].client_id==client_id) return &g_desktop_tasks.entries[i];
    return (struct nova_desktop_task_entry *)0;
}

static int desktop_staging_has_client(unsigned int client_id) {
    for (unsigned int i=0U; i<g_desktop_tasks.staging_count; i++)
        if (g_desktop_tasks.staging_entries[i].client_id==client_id) return 1;
    return 0;
}


static int desktop_task_asset_id_valid(const char asset_id[NOVA_DESKTOP_TASK_ICON_ASSET_ID_BYTES]) {
    unsigned long nul=NOVA_DESKTOP_TASK_ICON_ASSET_ID_BYTES;
    for (unsigned long i=0U; i<NOVA_DESKTOP_TASK_ICON_ASSET_ID_BYTES; i++) {
        if (asset_id[i]=='\0') { nul=i; break; }
    }
    if (nul==0U || nul==NOVA_DESKTOP_TASK_ICON_ASSET_ID_BYTES) return 0;
    for (unsigned long i=0U; i<nul; i++) {
        char c=asset_id[i];
        if (!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='.'||c=='_'||c=='-')) return 0;
    }
    return 1;
}

static int consume_desktop_task_icon_message(const struct nova_desktop_task_icon_message *m) {
    if (!m || m->magic!=NOVA_DESKTOP_PROTOCOL_MAGIC || m->version!=NOVA_DESKTOP_PROTOCOL_VERSION ||
        m->opcode!=NOVA_DESKTOP_OP_TASK_MODEL_ICON || m->size!=sizeof(*m) ||
        !g_desktop_tasks.staging || m->total_count!=g_desktop_tasks.staging_expected ||
        m->catalog_generation!=g_desktop_tasks.staging_generation ||
        m->index>=g_desktop_tasks.staging_count || m->index>=m->total_count ||
        m->client_id==0U || m->icon_format!=NOVA_DESKTOP_TASK_ICON_FORMAT_A8 ||
        m->icon_width!=NOVA_DESKTOP_TASK_ICON_WIDTH ||
        m->icon_height!=NOVA_DESKTOP_TASK_ICON_HEIGHT ||
        m->icon_bytes!=NOVA_DESKTOP_TASK_ICON_BYTES ||
        !desktop_task_asset_id_valid(m->asset_id)) {
        g_desktop_tasks.rejects++;
        g_desktop_tasks.staging=0;
        nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=icon-invalid");
        return 1;
    }
    struct nova_desktop_task_entry *entry=&g_desktop_tasks.staging_entries[m->index];
    if (entry->client_id!=m->client_id || !(entry->flags & NOVA_DESKTOP_TASK_FLAG_HAS_ICON) || entry->icon_ready) {
        g_desktop_tasks.rejects++;
        g_desktop_tasks.staging=0;
        nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=icon-binding-invalid");
        return 1;
    }
    entry->icon_ready=1U;
    entry->icon_format=m->icon_format;
    entry->icon_width=m->icon_width;
    entry->icon_height=m->icon_height;
    entry->icon_bytes=m->icon_bytes;
    unsigned int i=0U;
    while (m->asset_id[i] && i+1U<sizeof(entry->icon_asset_id)) { entry->icon_asset_id[i]=m->asset_id[i]; i++; }
    entry->icon_asset_id[i]='\0';
    nova_copy(entry->icon_digest,m->digest,sizeof(entry->icon_digest));
    nova_copy(entry->icon_pixels,m->pixels,sizeof(entry->icon_pixels));
    nova_puts("[nova-compositor] desktop_task_icon=STAGED index="); nova_put_u64(m->index);
    nova_puts(" client="); nova_put_u64(m->client_id);
    nova_puts(" asset="); nova_puts(entry->icon_asset_id); nova_putln("");
    return 1;
}

static int consume_desktop_task_message(const struct nova_desktop_task_message *m) {
    if (!m || m->magic!=NOVA_DESKTOP_PROTOCOL_MAGIC || m->version!=NOVA_DESKTOP_PROTOCOL_VERSION ||
        m->size!=sizeof(*m) || m->reserved!=0U || m->total_count>NOVA_DESKTOP_TASK_MAX_ENTRIES) {
        g_desktop_tasks.rejects++;
        g_desktop_tasks.staging=0;
        nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=header-invalid");
        return 1;
    }
    if (m->opcode==NOVA_DESKTOP_OP_TASK_MODEL_RESET) {
        if (m->index!=0U || m->client_id!=0U || m->task_flags!=0U || m->display_name[0]!='\0') {
            g_desktop_tasks.rejects++;
            g_desktop_tasks.staging=0;
            nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=reset-invalid");
            return 1;
        }
        nova_zero(g_desktop_tasks.staging_entries,sizeof(g_desktop_tasks.staging_entries));
        g_desktop_tasks.staging=1;
        g_desktop_tasks.staging_count=0U;
        g_desktop_tasks.staging_expected=m->total_count;
        g_desktop_tasks.staging_generation=m->catalog_generation;
        return 1;
    }
    if (m->opcode==NOVA_DESKTOP_OP_TASK_MODEL_DEFINE) {
        if (!g_desktop_tasks.staging || m->total_count!=g_desktop_tasks.staging_expected ||
            m->catalog_generation!=g_desktop_tasks.staging_generation ||
            m->index!=g_desktop_tasks.staging_count || m->index>=m->total_count ||
            m->client_id==0U || (m->task_flags & ~(NOVA_DESKTOP_TASK_FLAG_LAUNCHABLE | NOVA_DESKTOP_TASK_FLAG_HAS_ICON))!=0U ||
            !desktop_task_name_valid(m->display_name) || desktop_staging_has_client(m->client_id)) {
            g_desktop_tasks.rejects++;
            g_desktop_tasks.staging=0;
            nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=definition-invalid");
            return 1;
        }
        struct nova_desktop_task_entry *entry=&g_desktop_tasks.staging_entries[g_desktop_tasks.staging_count++];
        entry->client_id=m->client_id; entry->flags=m->task_flags;
        unsigned int i=0U;
        while (m->display_name[i] && i+1U<sizeof(entry->display_name)) { entry->display_name[i]=m->display_name[i]; i++; }
        entry->display_name[i]='\0';
        return 1;
    }
    if (m->opcode==NOVA_DESKTOP_OP_TASK_MODEL_COMMIT) {
        if (!g_desktop_tasks.staging || m->index!=g_desktop_tasks.staging_expected ||
            m->total_count!=g_desktop_tasks.staging_expected ||
            m->catalog_generation!=g_desktop_tasks.staging_generation ||
            m->client_id!=0U || m->task_flags!=0U || m->display_name[0]!='\0' ||
            g_desktop_tasks.staging_count!=g_desktop_tasks.staging_expected) {
            g_desktop_tasks.rejects++;
            g_desktop_tasks.staging=0;
            nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=commit-invalid");
            return 1;
        }
        for (unsigned int i=0U; i<g_desktop_tasks.staging_count; i++) {
            struct nova_desktop_task_entry *entry=&g_desktop_tasks.staging_entries[i];
            if ((entry->flags & NOVA_DESKTOP_TASK_FLAG_HAS_ICON) && !entry->icon_ready) {
                g_desktop_tasks.rejects++;
                g_desktop_tasks.staging=0;
                nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=icon-missing");
                return 1;
            }
            if (!(entry->flags & NOVA_DESKTOP_TASK_FLAG_HAS_ICON) && entry->icon_ready) {
                g_desktop_tasks.rejects++;
                g_desktop_tasks.staging=0;
                nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=unexpected-icon");
                return 1;
            }
        }
        nova_zero(g_desktop_tasks.entries,sizeof(g_desktop_tasks.entries));
        nova_copy(g_desktop_tasks.entries,g_desktop_tasks.staging_entries,
                  sizeof(struct nova_desktop_task_entry)*g_desktop_tasks.staging_count);
        g_desktop_tasks.count=g_desktop_tasks.staging_count;
        g_desktop_tasks.generation=g_desktop_tasks.staging_generation;
        g_desktop_tasks.staging=0;
        g_desktop_tasks.commits++;
        g_scene.visual_generation++;
        nova_puts("[nova-compositor] desktop_task_model=COMMITTED entries="); nova_put_u64(g_desktop_tasks.count);
        nova_puts(" generation="); nova_put_u64((unsigned long)g_desktop_tasks.generation); nova_putln("");
        return 1;
    }
    g_desktop_tasks.rejects++;
    g_desktop_tasks.staging=0;
    nova_putln("[nova-compositor] desktop_task_model=REJECTED reason=opcode-invalid");
    return 1;
}

static int send_desktop_task_event(unsigned int client_id, unsigned int action) {
    if (g_desktop_fd<0 || !g_desktop.connected || !client_id || !action) return 0;
    struct nova_desktop_message m; nova_zero(&m,sizeof(m));
    m.magic=NOVA_DESKTOP_PROTOCOL_MAGIC; m.version=NOVA_DESKTOP_PROTOCOL_VERSION;
    m.opcode=NOVA_DESKTOP_OP_TASK_EVENT; m.size=sizeof(m); m.client_id=client_id; m.action=action;
    m.sequence=++g_desktop.sequence; m.cursor_x=g_render.cursor_x; m.cursor_y=g_render.cursor_y;
    long n=nova_write(g_desktop_fd,&m,sizeof(m)); if ((unsigned long)n!=sizeof(m)) return 0;
    if(action==NOVA_DESKTOP_ACTION_LAUNCH){g_launch_focus_client=client_id;g_launch_focus_deadline=nova_render_clock(1)+90000000000ULL;}
    g_desktop.task_events++; g_desktop.last_client_id=client_id; g_desktop.last_action=action;
    nova_puts("[nova-compositor] desktop_task_event client="); nova_put_u64(client_id);
    nova_puts(" action="); nova_put_u64(action); nova_putln("");
    return 1;
}

/* R2 dock maps only to EXISTING authenticated desktop task events.
 * No new privileges or IPC protocol, and no extra hit targets when not drawn. */
/* Shared R7 system/task dock geometry, all actual pointer events match pixels. */
static unsigned int r7_dock_task_count(unsigned int width){
    if(width<400U)return 0U;
    unsigned int max=(width-44U)/NOVA_UI_DOCK_PITCH;
    return max>NOVA_DOCK_SYSTEM_ITEMS?(max-NOVA_DOCK_SYSTEM_ITEMS<g_desktop_tasks.count?max-NOVA_DOCK_SYSTEM_ITEMS:g_desktop_tasks.count):0U;
}
static unsigned r58_dock_packages(unsigned width,unsigned *ids){
 if(width<400)return 0;unsigned max=(width-44U)/NOVA_UI_DOCK_PITCH,used=NOVA_DOCK_SYSTEM_ITEMS+r7_dock_task_count(width),n=0;
 for(unsigned i=0;i<4&&used+n<max;i++)if(g_sw.ready&&g_sw.installed[i]==0){ids[n++]=i;}return n;
}
static int r7_dock_start(unsigned int width){
    unsigned ids[4];unsigned int items=NOVA_DOCK_SYSTEM_ITEMS+r7_dock_task_count(width)+r58_dock_packages(width,ids);
    return ((int)width-(int)(items*NOVA_UI_DOCK_PITCH+NOVA_DOCK_FRAME_PAD))/2;
}
static int r7_dock_top(unsigned int height){return (int)height-88;}
static int r19_dock_slot_x(int left,unsigned int i){return left+12+(int)(i*NOVA_UI_DOCK_PITCH)+(i>=NOVA_DOCK_SYSTEM_ITEMS?10:0);}
static int r7_dock_system_hit(int x,int y){
    if(g_r2_canvas_width<400U||g_r2_canvas_height<300U)return 0;
    int left=r7_dock_start(g_r2_canvas_width),top=r7_dock_top(g_r2_canvas_height);
    for(unsigned int k=0U;k<NOVA_DOCK_SYSTEM_ITEMS;k++){
        int sx=r19_dock_slot_x(left,k);
        if(x>=sx&&x<sx+56&&y>=top+5&&y<top+70)return (int)k+1;
    }
    return 0;
}
static int nova_r2_dock_hit(int x,int y,unsigned int *client_id,unsigned int *action){
    if(!g_desktop.connected||!client_id||!action)return 0;
    unsigned int count=r7_dock_task_count(g_r2_canvas_width);
    int left=r7_dock_start(g_r2_canvas_width),top=r7_dock_top(g_r2_canvas_height);
    for(unsigned int i=0U;i<count;i++){
        int sx=r19_dock_slot_x(left,i+NOVA_DOCK_SYSTEM_ITEMS);
        if(x<sx||x>=sx+56||y<top+5||y>=top+70)continue;
        const struct nova_desktop_task_entry *entry=&g_desktop_tasks.entries[i];
        unsigned int live=client_surface_count_for(entry->client_id);
        *client_id=entry->client_id;
        *action=(!live&&(entry->flags&NOVA_DESKTOP_TASK_FLAG_LAUNCHABLE))?
          NOVA_DESKTOP_ACTION_LAUNCH:NOVA_DESKTOP_ACTION_ACTIVATE;
        return 1;
    }
    return 0;
}
static int desktop_task_hit(int x, int y, unsigned int *client_id, unsigned int *action) {
    if (!client_id || !action) return 0;
    *client_id=0U; *action=NOVA_DESKTOP_ACTION_NONE;
    if (nova_r2_dock_hit(x,y,client_id,action)) return 1;
    if (y<6 || y>=32) return 0;
    const int task_base=NOVA_UI_TASK_BASE;
    const int task_stride=NOVA_UI_TASK_PITCH;
    const int task_width=80;
    const int close_width=20;
    const int launch_stride=70;
    const int launch_width=60;
    int launch_base=task_base+(int)g_desktop_tasks.count*task_stride+10;
   
    for (unsigned int i=0U; i<g_desktop_tasks.count; i++) {
        struct nova_desktop_task_entry *task=&g_desktop_tasks.entries[i];
        int tx=task_base+(int)i*task_stride;
        if(tx+100>(int)g_r2_canvas_width-140)break;
        if (x>=tx && x<tx+(client_surface_count_for(task->client_id)?task_width:task_width+close_width)) { *client_id=task->client_id; *action=(!client_surface_count_for(task->client_id)&&(task->flags&NOVA_DESKTOP_TASK_FLAG_LAUNCHABLE))?NOVA_DESKTOP_ACTION_LAUNCH:NOVA_DESKTOP_ACTION_ACTIVATE; return 1; }
        if (client_surface_count_for(task->client_id)&&x>=tx+task_width && x<tx+task_width+close_width) { *client_id=task->client_id; *action=NOVA_DESKTOP_ACTION_CLOSE; return 1; }
        int lx=launch_base+(int)i*launch_stride;
        if (!NOVA_R24_OPTIMIZED&&(task->flags & NOVA_DESKTOP_TASK_FLAG_LAUNCHABLE) && !client_surface_count_for(task->client_id) && lx+60<(int)g_r2_canvas_width-140 && x>=lx && x<lx+launch_width) {
            *client_id=task->client_id; *action=NOVA_DESKTOP_ACTION_LAUNCH; return 1;
        }
    }
    return 0;
}

static int desktop_send_launch_event(unsigned int client_id) {
    struct nova_client_connection *conn=connection_for_client_id(client_id);
    if (!conn || !conn->used || conn->fd<0) return 0;
    struct nova_surface_event ev; nova_zero(&ev,sizeof(ev));
    ev.magic=NOVA_SURFACE_PROTOCOL_MAGIC; ev.version=NOVA_SURFACE_PROTOCOL_VERSION;
    ev.type=NOVA_SURFACE_EVENT_LAUNCH; ev.size=sizeof(ev); ev.client_id=client_id; ev.surface_id=0U;
    ev.sequence=(unsigned int)(g_client.events_routed+1UL); ev.modifiers=g_input_modifiers;
    long n=nova_write(conn->fd,&ev,sizeof(ev)); if ((unsigned long)n!=sizeof(ev)) return 0;
    g_client.events_routed++;
    return 1;
}

static int desktop_activate_client(unsigned int client_id) {
    struct nova_client_surface *s=primary_surface_for_client(client_id);
    if (!s) return 0;
    s->minimized=0;g_scene.visual_generation++;
    g_scene.focus_index=0U; set_client_focus(s->surface_id);
    g_desktop.activates++; g_desktop.last_client_id=client_id; g_desktop.last_action=NOVA_DESKTOP_ACTION_ACTIVATE;
    nova_puts("[nova-compositor] desktop_activate client="); nova_put_u64(client_id);
    nova_puts(" surface="); nova_put_u64(s->surface_id); nova_putln("");
    return 1;
}

static int desktop_close_client(unsigned int client_id) {
    unsigned int sent=0U;
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) {
        struct nova_client_surface *s=&g_surfaces[i];
        if (s->used && s->committed && s->client_id==client_id && s->role==NOVA_SURFACE_ROLE_TOPLEVEL) {
            if (send_close_request(s)) sent++;
        }
    }
    if (!sent) return 0;
    g_desktop.closes++; g_desktop.last_client_id=client_id; g_desktop.last_action=NOVA_DESKTOP_ACTION_CLOSE;
    nova_puts("[nova-compositor] desktop_close client="); nova_put_u64(client_id);
    nova_puts(" requests="); nova_put_u64(sent); nova_putln("");
    return 1;
}

static int desktop_launch_client(unsigned int client_id) {
    if (client_surface_count_for(client_id)!=0U) return desktop_activate_client(client_id);
    if (!desktop_send_launch_event(client_id)) return 0;
    g_desktop.launches++; g_desktop.last_client_id=client_id; g_desktop.last_action=NOVA_DESKTOP_ACTION_LAUNCH;
    nova_puts("[nova-compositor] desktop_launch client="); nova_put_u64(client_id); nova_putln(" mode=resident-window-reopen");
    return 1;
}

static int consume_desktop_message(int client) {
    union {
        struct nova_desktop_message control;
        struct nova_desktop_task_message task;
        struct nova_desktop_task_icon_message icon;
    } packet;
    struct nova_iovec iov;
    struct nova_msghdr msg;
    nova_zero(&packet,sizeof(packet));
    nova_zero(&iov,sizeof(iov));
    nova_zero(&msg,sizeof(msg));
    iov.iov_base=&packet; iov.iov_len=sizeof(packet);
    msg.msg_iov=&iov; msg.msg_iovlen=1;
    long n=nova_recvmsg(client,&msg,0);
    if (n==-NOVA_EAGAIN) return 1;
    if (n<=0) return 0;
    if (msg.msg_flags & (NOVA_MSG_TRUNC|NOVA_MSG_CTRUNC)) {
        nova_putln("[nova-compositor] desktop_control=REJECTED reason=protocol_message_truncated");
        return 1;
    }

    if ((unsigned long)n==sizeof(struct nova_desktop_task_icon_message)) {
        g_desktop.messages++;
        return consume_desktop_task_icon_message(&packet.icon);
    }
    if ((unsigned long)n==sizeof(struct nova_desktop_task_message)) {
        g_desktop.messages++;
        return consume_desktop_task_message(&packet.task);
    }
    if ((unsigned long)n!=sizeof(struct nova_desktop_message)) {
        nova_putln("[nova-compositor] desktop_control=REJECTED reason=protocol_message_size");
        return 1;
    }

    struct nova_desktop_message *m=&packet.control;
    if (m->magic!=NOVA_DESKTOP_PROTOCOL_MAGIC || m->version!=NOVA_DESKTOP_PROTOCOL_VERSION || m->size!=sizeof(*m)) {
        nova_putln("[nova-compositor] desktop_control=REJECTED reason=protocol_message_invalid"); return 1;
    }
    g_desktop.messages++; g_desktop.protocol_version=m->version;
    if (m->opcode==NOVA_DESKTOP_OP_HELLO) {
        g_desktop.connected=1; nova_putln("[nova-compositor] desktop_control=CONNECTED protocol=1 shell-policy=dynamic-taskbar-v1");
    } else if (m->opcode==NOVA_DESKTOP_OP_HEARTBEAT) {
        return 1;
    } else if (m->opcode==NOVA_DESKTOP_OP_ACTIVATE || m->opcode==NOVA_DESKTOP_OP_CLOSE || m->opcode==NOVA_DESKTOP_OP_LAUNCH) {
        struct nova_desktop_task_entry *task=desktop_task_for_client(m->client_id);
        if (!task) { nova_putln("[nova-compositor] desktop_control=REJECTED reason=client_not_in_task_model"); return 1; }
        if (m->opcode==NOVA_DESKTOP_OP_LAUNCH && !(task->flags & NOVA_DESKTOP_TASK_FLAG_LAUNCHABLE)) {
            nova_putln("[nova-compositor] desktop_control=REJECTED reason=task_not_launchable"); return 1;
        }
        g_desktop.commands++;
        if (m->opcode==NOVA_DESKTOP_OP_ACTIVATE) (void)desktop_activate_client(m->client_id);
        else if (m->opcode==NOVA_DESKTOP_OP_CLOSE) (void)desktop_close_client(m->client_id);
        else (void)desktop_launch_client(m->client_id);
    }
    return 1;
}

static unsigned int r17_round_coverage(unsigned int x,unsigned int y,unsigned int w,unsigned int h){
    const unsigned int radius=12U;
    if(w<radius*2U||h<radius*2U)return 255U;
    if((x>=radius&&x<w-radius)||(y>=radius&&y<h-radius))return 255U;
    int cx=(int)(x<radius?radius:w-radius)*4;
    int cy=(int)(y<radius?radius:h-radius)*4;
    unsigned int inside=0;
    for(int sy=0;sy<4;sy++)for(int sx=0;sx<4;sx++){
        int dx=(int)x*4+sx-cx,dy=(int)y*4+sy-cy;
        if(dx*dx+dy*dy<=(int)(radius*radius*16U))inside++;
    }
    return inside*255U/16U;
}

#ifdef NOVA_RENDER_TEST_REFERENCE
static int g_test_reference_blit;
#endif
static void blit_client_buffer(unsigned char *base, unsigned int width, unsigned int height,
                               unsigned int pitch, const struct nova_client_surface *s) {
    struct nova_client_buffer *buf=find_client_buffer(s->client_id,s->buffer_id);
    if (!buf || !buf->map || pointer_is_error(buf->map)) return;
    int dst_x=s->x, dst_y=s->y;
    unsigned int copy_w=s->width<buf->width?s->width:buf->width;
    unsigned int copy_h=s->height<buf->height?s->height:buf->height;
    if (dst_x<0 || dst_y<0) return;
    if ((unsigned int)dst_x>=width || (unsigned int)dst_y>=height) return;
    if (copy_w>width-(unsigned int)dst_x) copy_w=width-(unsigned int)dst_x;
    if (copy_h>height-(unsigned int)dst_y) copy_h=height-(unsigned int)dst_y;
    const unsigned char *src=(const unsigned char *)buf->map;
    for (unsigned int y=0;y<copy_h;y++) {
        unsigned int *dst_row=(unsigned int *)(base+(unsigned long)(dst_y+(int)y)*pitch)+(unsigned int)dst_x;
        const unsigned int *src_row=(const unsigned int *)(src+(unsigned long)y*buf->stride);
        /* Rounded coverage is needed only in the two corner bands. Opaque
         * spans retain XRGB masking and avoid per-pixel geometry branches. */
        unsigned int left=0,right=copy_w;
        if(s->width>=24U&&s->height>=24U&&(y<12U||y>=s->height-12U)){
            left=copy_w<12U?copy_w:12U;right=copy_w<s->width-12U?copy_w:s->width-12U;
        }
#ifdef NOVA_RENDER_TEST_REFERENCE
        if(g_test_reference_blit)left=right=copy_w;
#endif
        for(unsigned int x=0;x<left;x++){unsigned int a=r17_round_coverage(x,y,s->width,s->height);if(a==255U)dst_row[x]=src_row[x]&0x00ffffffU;else if(a)dst_row[x]=nova_mix_rgb(dst_row[x],src_row[x],a,255U);}
        for(unsigned int x=left;x<right;x++)dst_row[x]=src_row[x]&0x00ffffffU;
        for(unsigned int x=right;x<copy_w;x++){unsigned int a=r17_round_coverage(x,y,s->width,s->height);if(a==255U)dst_row[x]=src_row[x]&0x00ffffffU;else if(a)dst_row[x]=nova_mix_rgb(dst_row[x],src_row[x],a,255U);}
    }
}

static int r17_title_button_at(const struct nova_client_surface *s,int px,int py);
#ifdef NOVA_RENDER_TEST_REFERENCE
static int g_test_reference_shadow;
#endif
static void draw_client_surfaces(unsigned char *base, unsigned int width, unsigned int height, unsigned int pitch) {
    unsigned int order[NOVA_SURFACE_MAX_CLIENT_SURFACES];
    unsigned int count=0;
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) if (g_surfaces[i].used && g_surfaces[i].committed && !g_surfaces[i].minimized) order[count++]=i;
    for (unsigned int i=1;i<count;i++) {
        unsigned int key=order[i], j=i;
        while (j>0 && g_surfaces[order[j-1]].z_index>g_surfaces[key].z_index) { order[j]=order[j-1]; j--; }
        order[j]=key;
    }
    unsigned terminal_drawn=0;
    for (unsigned int oi=0;oi<count;oi++) {
        struct nova_client_surface *s=&g_surfaces[order[oi]];
        if(!terminal_drawn&&g_terminal.visible&&s->z_index>=g_terminal.z_index){
            r25_terminal_draw(base,width,height,pitch);terminal_drawn=1;
        }
        struct nova_client_buffer *buf=find_client_buffer(s->client_id,s->buffer_id);
        if (!buf) continue;
        unsigned int focused=(g_client.focus_surface==s->surface_id)?1U:0U;
        const struct r8_palette *palette=r8_colors();
        int shadow_elide=buf->map&&buf->width>=s->width&&buf->height>=s->height&&s->x>=0&&s->y>=0;
#ifdef NOVA_RENDER_TEST_REFERENCE
        if(g_test_reference_shadow)shadow_elide=0;
#endif
        r19_shadow(base,width,height,pitch,s->x,s->y,s->width,s->height,focused?32U:22U,shadow_elide);
        blit_client_buffer(base,width,height,pitch,s);
        if(s->role==NOVA_SURFACE_ROLE_TOPLEVEL){
            unsigned int title_h=s->height<NOVA_TOPLEVEL_TITLEBAR_HEIGHT?s->height:NOVA_TOPLEVEL_TITLEBAR_HEIGHT;
            unsigned int title_color=(g_render.theme&1U)?0x00e6e8edU:0x002b303bU;
            title_color=nova_ui_palette_for(g_session_theme.choice).toolbar;
            unsigned int title_luma=((title_color>>16&255U)*54U+(title_color>>8&255U)*183U+(title_color&255U)*19U)/256U;
            unsigned int title_ink=title_luma>140U?(focused?0x002c3a42U:0x0066737cU):(focused?0x00e1eaf2U:0x00a6b3c0U);
            r8_alpha_round(base,width,height,pitch,s->x,s->y,s->width,title_h,10U,title_color,255U);
            if(title_h>12U)fill_rect(base,width,height,pitch,s->x,s->y+14,s->width,title_h-14U,title_color);
            if(s->width>150U){struct nova_ui_canvas canvas={base,width,height,pitch};
                char title_text[NOVA_SURFACE_TITLE_BYTES+4];nova_ui_ellipsis(s->title,title_text,sizeof(title_text),NOVA_UI_HEADING,s->width-104U);
                nova_ui_text(canvas,s->x+13,s->y+19,NOVA_UI_HEADING,1,title_ink,title_text,s->x+10,s->y,s->width-100U,title_h);}
            for(int button=1;button<=3;button++){
                int bx=s->x+(int)s->width-6-button*24,by=s->y+5;
                unsigned int hover=r17_title_button_at(s,g_render.cursor_x,g_render.cursor_y)==button;
                unsigned int color=button==1?((g_render.theme&1U)?0x00b52844U:0x00ef8192U):((g_render.theme&1U)?0x004f5b6cU:palette->muted);
                color=button==1?(title_luma>140U?0x009c4559U:0x00edabb5U):title_ink;
                if(hover){struct nova_ui_canvas bc={base,width,height,pitch};struct nova_ui_palette bp=nova_ui_palette_for(title_luma>140U?2U:1U);(void)nova_ui_button(bc,bx-2,by-1,22,21,bp,NOVA_UI_HOVER);}
                struct nova_ui_canvas canvas={base,width,height,pitch};
                if(button==1){
                    nova_ui_line(canvas,bx+5,by+5,bx+12,by+12,color);
                    nova_ui_line(canvas,bx+12,by+5,bx+5,by+12,color);
                }else if(button==2){
                    nova_ui_line(canvas,bx+5,by+5,bx+12,by+5,color);
                    nova_ui_line(canvas,bx+12,by+5,bx+12,by+12,color);
                    nova_ui_line(canvas,bx+12,by+12,bx+5,by+12,color);
                    nova_ui_line(canvas,bx+5,by+12,bx+5,by+5,color);
                }else nova_ui_line(canvas,bx+5,by+11,bx+12,by+11,color);
            }
        }
        unsigned int border=focused?0x0095adc9U:0x006d7c90U;
        fill_rect(base,width,height,pitch,s->x+12,s->y+(int)s->height-1,s->width>24U?s->width-24U:0U,1U,border);
        fill_rect(base,width,height,pitch,s->x,s->y+12,1U,s->height>24U?s->height-24U:0U,border);
        fill_rect(base,width,height,pitch,s->x+(int)s->width-1,s->y+12,1U,s->height>24U?s->height-24U:0U,border);
    }
    if(g_terminal.visible&&!terminal_drawn)r25_terminal_draw(base,width,height,pitch);
}

static void draw_fallback_pattern(void *map, unsigned int width, unsigned int height,
                                  unsigned int pitch, unsigned long frame_sequence) {
    unsigned char *base=(unsigned char *)map;
    unsigned int moving_limit=width>NOVA_RENDER_BLOCK?width-NOVA_RENDER_BLOCK:1U;
    unsigned int moving_x=moving_limit?(unsigned int)((frame_sequence*17UL)%moving_limit):0U;
    unsigned int moving_y=height>(NOVA_RENDER_BLOCK+24U)?height/4U:0U;
    clamp_cursor(width,height);
    for (unsigned int y=0;y<height;y++) {
        unsigned int *row=(unsigned int *)(base+(unsigned long)y*pitch);
        for (unsigned int x=0;x<width;x++) {
            unsigned int band=width?(x*4U)/width:0U;
            unsigned int color=background_color(g_render.theme,band);
            if (x<4U||y<4U||x+4U>=width||y+4U>=height) color=0;
            if (x>=moving_x&&x<moving_x+NOVA_RENDER_BLOCK&&y>=moving_y&&y<moving_y+NOVA_RENDER_BLOCK) color=0x00ff8800U;
            row[x]=color;
        }
    }
}


static void draw_task_icon(unsigned char *base, unsigned int width, unsigned int height, unsigned int pitch,
                           int x0, int y0, const struct nova_desktop_task_entry *task,
                           unsigned int color) {
    if (!task || !task->icon_ready || task->icon_format!=NOVA_DESKTOP_TASK_ICON_FORMAT_A8 ||
        task->icon_width!=NOVA_DESKTOP_TASK_ICON_WIDTH || task->icon_height!=NOVA_DESKTOP_TASK_ICON_HEIGHT ||
        task->icon_bytes!=NOVA_DESKTOP_TASK_ICON_BYTES) return;
    for (unsigned int y=0U; y<task->icon_height; y++) {
        int dy=y0+(int)y;
        if (dy<0 || (unsigned int)dy>=height) continue;
        for (unsigned int x=0U; x<task->icon_width; x++) {
            int dx=x0+(int)x;
            if (dx<0 || (unsigned int)dx>=width) continue;
            if (task->icon_pixels[y*task->icon_width+x] < 128U) continue;
            unsigned int *row=(unsigned int *)(base+(unsigned long)dy*pitch);
            row[(unsigned int)dx]=color & 0x00ffffffU;
        }
    }
}

/* Built-in Home / Quick controls plus authenticated, live task icons.
 * Unlike R6's two-icon capsule these are all working controls. */

static void nova_r2_dock(unsigned char*b,unsigned int w,unsigned int h,unsigned int p){
 if(w<400U||h<300U)return;unsigned ids[4],packages=r58_dock_packages(w,ids);unsigned int count=r7_dock_task_count(w),items=NOVA_DOCK_SYSTEM_ITEMS+count+packages,pw=items*NOVA_UI_DOCK_PITCH+NOVA_DOCK_FRAME_PAD;
 int left=r7_dock_start(w),top=r7_dock_top(h);struct nova_ui_canvas c={b,w,h,p};
 r8_alpha_round(b,w,h,p,left-1,top+3,pw+2U,73U,21U,0x0005090d,35U);
 r8_alpha_round(b,w,h,p,left,top,pw,72U,20U,g_session_theme.choice==1?0x0026303dU:0x00dbe6e3U,224U);
 r8_alpha_round(b,w,h,p,left+1,top+1,pw-2U,70U,19U,g_session_theme.choice==1?0x00394758U:0x00f4f8f6U,108U);
 nova_ui_round(c,left+12+NOVA_DOCK_SYSTEM_ITEMS*NOVA_UI_DOCK_PITCH+2,top+16,1,38,0,0x00abbab8);
 for(unsigned int i=0;i<items;i++){
  int bx=r19_dock_slot_x(left,i),hover=g_render.cursor_x>=bx&&g_render.cursor_x<bx+56&&g_render.cursor_y>=top+5&&g_render.cursor_y<top+70;
  if(hover)r8_alpha_round(b,w,h,p,bx,top+5,56,56,14,0x00ffffff,110);
  if(i<NOVA_DOCK_SYSTEM_ITEMS)nova_ui_dock_icon(c,bx+4,top+8,i==0?0:i==1?4:i==2?6:7);
  else if(i>=NOVA_DOCK_SYSTEM_ITEMS+count)nova_ui_dock_icon(c,bx+4,top+8,8+ids[i-NOVA_DOCK_SYSTEM_ITEMS-count]);
  else{const struct nova_desktop_task_entry*task=&g_desktop_tasks.entries[i-NOVA_DOCK_SYSTEM_ITEMS];
   if(task->client_id==4)nova_ui_dock_icon(c,bx+4,top+8,5);
   else if(task->client_id==3)nova_ui_dock_icon(c,bx+4,top+8,3);
   else if(task->client_id<=2)nova_ui_app_icon(c,bx+4,top+8,48,task->client_id);
   else{int rid=r12_known_demo_icon(task);if(rid>=0)r12_icon(b,w,h,p,bx+8,top+12,40,(unsigned int)rid);
    else if(task->icon_ready)draw_task_icon(b,w,h,p,bx+16,top+16,task,0x002b3e46);else{nova_ui_round(c,bx+4,top+8,48,48,12,0x00495e70);r3_text(b,w,h,p,bx+13,top+23,0,0x00f3f7fb,"App",bx+6,top+12,44,40);}}
  }
  unsigned int live=i<NOVA_DOCK_SYSTEM_ITEMS?((i==0&&g_r7_library_visible)||(i==1&&g_r7_controls_visible)||(i==2&&g_terminal.fd>=0)||(i==3&&g_sw.visible)):i>=NOVA_DOCK_SYSTEM_ITEMS+count?((g_sw.running>>ids[i-NOVA_DOCK_SYSTEM_ITEMS-count])&1U):client_surface_count_for(g_desktop_tasks.entries[i-NOVA_DOCK_SYSTEM_ITEMS].client_id);
  if(live){unsigned int active=0,visible=0;
   for(unsigned int k=0;k<NOVA_SURFACE_MAX_CLIENT_SURFACES&&i>=NOVA_DOCK_SYSTEM_ITEMS&&i<NOVA_DOCK_SYSTEM_ITEMS+count;k++)if(g_surfaces[k].used&&g_surfaces[k].committed&&g_surfaces[k].client_id==g_desktop_tasks.entries[i-NOVA_DOCK_SYSTEM_ITEMS].client_id){if(!g_surfaces[k].minimized)visible=1;if(g_surfaces[k].surface_id==g_client.focus_surface)active=1;}
   if(i==3){visible=g_sw.visible;active=g_sw.visible&&g_sw.focused;}
   if(i>=NOVA_DOCK_SYSTEM_ITEMS+count){visible=g_sw.visible&&g_sw.page==ids[i-NOVA_DOCK_SYSTEM_ITEMS-count]+1;active=visible&&g_sw.focused;}
   if(i==2){visible=g_terminal.visible;active=g_terminal.visible&&g_terminal.focused&&!g_r7_controls_visible&&!g_r7_library_visible&&!r48_desktop_menu_open();}
   unsigned state=nova_dock_state(live,visible,active,i>=NOVA_DOCK_SYSTEM_ITEMS&&((g_terminal.visible&&g_terminal.focused)||g_r7_controls_visible||g_r7_library_visible||r48_desktop_menu_open()));
   unsigned ink=g_session_theme.choice==1?0x00a0d8cbU:0x002b5b52U;
   if(i<2||state>=2)r8_alpha_round(b,w,h,p,bx+(state==3?19:25),top+63,state==3?18U:6U,3,2,ink,245);
   else{r8_alpha_round(b,w,h,p,bx+23,top+62,10,5,2,ink,190);r8_alpha_round(b,w,h,p,bx+25,top+63,6,3,1,g_session_theme.choice==1?0x00394758:0x00e3eeeb,255);}

  }
  if(hover){const char*name=i==0?"Uygulamalar":i==1?"Ayarlar":i==2?"Terminal (Ctrl+Alt+T)":i==3?"Nova Software":i>=NOVA_DOCK_SYSTEM_ITEMS+count?nova_sw_titles[ids[i-NOVA_DOCK_SYSTEM_ITEMS-count]]:r3_short_task_name(g_desktop_tasks.entries[i-NOVA_DOCK_SYSTEM_ITEMS].display_name);
   unsigned int tw=nova_ui_measure(name,NOVA_UI_HEADING,1)+24;int tx=bx+28-(int)tw/2;if(tx<4)tx=4;if(tx+(int)tw>(int)w-4)tx=(int)w-4-(int)tw;
   r8_alpha_round(b,w,h,p,tx,top-36,tw,27,9,0x00252e35,244);nova_ui_text(c,tx+12,top-17,NOVA_UI_HEADING,1,0xf7faf8,name,tx,top-36,tw,27);
  }
 }
}
static void draw_desktop_taskbar(unsigned char*b,unsigned int w,unsigned int h,unsigned int p){
 if(!g_scene.panel_height||h<g_scene.panel_height)return;struct nova_ui_canvas c={b,w,h,p};
 struct nova_client_surface*focused=g_client.focus_surface?find_client_surface(g_client.focus_surface):(struct nova_client_surface*)0;
 unsigned int active=focused?focused->client_id:0;const int task_base=NOVA_UI_TASK_BASE,task_stride=NOVA_UI_TASK_PITCH;

 for(unsigned int i=0;i<g_desktop_tasks.count;i++){
  const struct nova_desktop_task_entry*t=&g_desktop_tasks.entries[i];int tx=task_base+(int)i*task_stride;if(tx+100>(int)w-140)break;
  int hover=g_render.cursor_x>=tx&&g_render.cursor_x<tx+100&&g_render.cursor_y>=6&&g_render.cursor_y<32;
  if(hover||active==t->client_id)r8_alpha_round(b,w,h,p,tx,6,100,26,7,g_session_theme.choice==0?0x00304b58U:0x00e6efebU,hover?40:24);
  nova_ui_text(c,tx+9,24,active==t->client_id?NOVA_UI_HEADING:NOVA_UI_BODY,1,g_session_theme.choice==0?0x263042:(active==t->client_id?0xf4f8f6:0xc4d2ce),r3_short_task_name(t->display_name),tx+6,6,72,26);
  if(hover&&client_surface_count_for(t->client_id)){nova_ui_line(c,tx+86,15,tx+92,21,(g_session_theme.choice==0?0x00405765:0xd0ded8));nova_ui_line(c,tx+92,15,tx+86,21,(g_session_theme.choice==0?0x00405765:0xd0ded8));}

 }
}
static void draw_scene(void *map,unsigned int width,unsigned int height,
                       unsigned int pitch,unsigned long frame_sequence){
    g_r2_canvas_width=width;g_r2_canvas_height=height;
    if(!g_scene.configured){draw_fallback_pattern(map,width,height,pitch,frame_sequence);return;}
    unsigned char *base=(unsigned char *)map;
    r3_background(base,width,height,pitch,g_render.theme);
    r3_panel(base,width,height,pitch,g_scene.panel_height);
    draw_desktop_taskbar(base,width,height,pitch);
    r48_desktop_draw(base,width,height,pitch);
    clamp_scene(width,height);
    /* Existing native app buffer path is unchanged. */
    draw_client_surfaces(base,width,height,pitch);
    r3_window(base,width,height,pitch,frame_sequence);
    r7_controls(base,width,height,pitch);
    r58_draw(base,width,height,pitch);
    nova_r2_dock(base,width,height,pitch);
    r48_desktop_menu_draw(base,width,height,pitch);
    r54_desktop_overlay_draw(base,width,height,pitch);
    clamp_cursor(width,height);
    r3_cursor(base,width,height,pitch);
}



/* R5 2x staging: render entire native NovaOS scene in logical coordinates,
 * then expand XRGB8888 into hardware scanout. No untrusted input controls bounds.
 * Performance and physical-pixel text quality must be measured separately. */
static void r5_draw_scene(void *map,unsigned int phys_w,unsigned int phys_h,
                          unsigned int pitch,unsigned long sequence){
    if(g_r5_scale==1U){ draw_scene(map,phys_w,phys_h,pitch,sequence); return; }
    const unsigned int lw=g_r5_logical_w, lh=g_r5_logical_h;
    if(!map || !lw || !lh || lw>NOVA_R5_MAX_LOGICAL_W || lh>NOVA_R5_MAX_LOGICAL_H ||
       phys_w!=lw*2U || phys_h!=lh*2U || pitch<phys_w*4U) return;
    draw_scene(g_r5_logical_pixels,lw,lh,lw*4U,sequence);
    unsigned char *dest=(unsigned char *)map;
    for(unsigned int y=0U;y<lh;y++){
        unsigned int *first=(unsigned int *)(dest+(unsigned long)(y*2U)*pitch);
        const unsigned int *src=g_r5_logical_pixels+(unsigned long)y*lw;
        for(unsigned int x=0U;x<lw;x++){
            unsigned int color=src[x]; first[x*2U]=color; first[x*2U+1U]=color;
        }
        /* The second scanline exactly matches the first, without touching padding. */
        nova_copy(dest+(unsigned long)(y*2U+1U)*pitch,first,(unsigned long)phys_w*4UL);
    }
}

static struct r24_clip r24_cursor_clip(int x,int y,unsigned int w,unsigned int h){int right=x+12,bottom=y+20;if(x<0)x=0;if(y<0)y=0;if(right>(int)w)right=(int)w;if(bottom>(int)h)bottom=(int)h;return (struct r24_clip){(unsigned short)x,(unsigned short)y,(unsigned short)right,(unsigned short)bottom};}
static int r24_render_scanout(struct nova_scanout_buffer*buf,unsigned int w,unsigned int h,unsigned long seq){
 unsigned long content=g_scene.visual_generation-g_r24_cursor_generation;
 if(NOVA_R24_OPTIMIZED&&g_r5_scale==1&&g_scene.configured&&buf->r24_valid&&buf->r24_content==content){
  buf->r24_clips[0]=r24_cursor_clip(buf->r24_x,buf->r24_y,w,h);r24_cursor_capture(buf,buf->map,w,h,buf->pitch,1);r24_cursor_capture(buf,buf->map,w,h,buf->pitch,0);buf->r24_clips[1]=r24_cursor_clip(buf->r24_x,buf->r24_y,w,h);r3_cursor(buf->map,w,h,buf->pitch);g_r24.partial++;return 1;
 }
 g_r24_capture=g_r5_scale==1?buf:0;r5_draw_scene(buf->map,w,h,buf->pitch,seq);g_r24_capture=0;buf->r24_content=content;g_r24.full++;return 0;
}
static void destroy_scanout_buffer(int fd, struct nova_scanout_buffer *buf) {
    if (!buf) return;
    if (buf->map && !pointer_is_error(buf->map) && buf->size)
        (void)nova_munmap(buf->map, (nova_size_t)buf->size);
    if (buf->fb_id) (void)nova_ioctl(fd, NOVA_DRM_IOCTL_MODE_RMFB, &buf->fb_id);
    if (buf->handle) {
        struct nova_drm_mode_destroy_dumb destroy;
        destroy.handle = buf->handle;
        (void)nova_ioctl(fd, NOVA_DRM_IOCTL_MODE_DESTROY_DUMB, &destroy);
    }
    nova_zero(buf, sizeof(*buf));
}

static int create_scanout_buffer(int fd, unsigned int width, unsigned int height,
                                 struct nova_scanout_buffer *buf,
                                 struct nova_display_failure *failure) {
    struct nova_drm_mode_create_dumb dumb;
    struct nova_drm_mode_fb_cmd2 fb;
    struct nova_drm_mode_map_dumb map_dumb;
    nova_zero(buf, sizeof(*buf));
    nova_zero(&dumb, sizeof(dumb));
    dumb.width = width;
    dumb.height = height;
    dumb.bpp = 32;
    long rc = nova_ioctl(fd, NOVA_DRM_IOCTL_MODE_CREATE_DUMB, &dumb);
    if (rc < 0 || !dumb.handle || !dumb.size) {
        set_display_failure(failure, "create_dumb_failed", rc);
        return 0;
    }
    buf->handle = dumb.handle;
    buf->pitch = dumb.pitch;
    buf->size = dumb.size;

    nova_zero(&fb, sizeof(fb));
    fb.width = width;
    fb.height = height;
    fb.pixel_format = NOVA_DRM_FORMAT_XRGB8888;
    fb.handles[0] = dumb.handle;
    fb.pitches[0] = dumb.pitch;
    rc = nova_ioctl(fd, NOVA_DRM_IOCTL_MODE_ADDFB2, &fb);
    if (rc < 0 || !fb.fb_id) {
        set_display_failure(failure, "addfb2_failed", rc);
        destroy_scanout_buffer(fd, buf);
        return 0;
    }
    buf->fb_id = fb.fb_id;

    nova_zero(&map_dumb, sizeof(map_dumb));
    map_dumb.handle = dumb.handle;
    rc = nova_ioctl(fd, NOVA_DRM_IOCTL_MODE_MAP_DUMB, &map_dumb);
    if (rc < 0) {
        set_display_failure(failure, "map_dumb_failed", rc);
        destroy_scanout_buffer(fd, buf);
        return 0;
    }
    buf->map = nova_mmap((void *)0, (nova_size_t)dumb.size,
                         NOVA_PROT_READ | NOVA_PROT_WRITE, NOVA_MAP_SHARED,
                         fd, (nova_off_t)map_dumb.offset);
    if (pointer_is_error(buf->map)) {
        set_display_failure(failure, "mmap_dumb_failed", (long)buf->map);
        buf->map = (void *)0;
        destroy_scanout_buffer(fd, buf);
        return 0;
    }
    return 1;
}

static void dirty_scanout(int fd, unsigned int fb_id) {
    struct nova_drm_mode_fb_dirty_cmd dirty;
    nova_zero(&dirty, sizeof(dirty));
    dirty.fb_id = fb_id;
    long rc = nova_ioctl(fd, NOVA_DRM_IOCTL_MODE_DIRTYFB, &dirty);
    if (rc < 0) {
        nova_puts("[nova-compositor] dirtyfb_errno=");
        nova_put_u64((unsigned long)(-rc));
        nova_putln("");
    }
}

static void shell_addr(struct nova_sockaddr_un *addr) {
    const char path[] = NOVA_SHELL_SOCKET_PATH;
    nova_zero(addr,sizeof(*addr)); addr->sun_family=NOVA_AF_UNIX;
    for (unsigned long i=0;i<sizeof(path)&&i<sizeof(addr->sun_path);i++) addr->sun_path[i]=path[i];
}

static int setup_shell_listener(void) {
    struct nova_sockaddr_un addr; shell_addr(&addr);
    (void)nova_unlink(NOVA_SHELL_SOCKET_PATH);
    long fd=nova_socket(NOVA_AF_UNIX,NOVA_SOCK_SEQPACKET|NOVA_SOCK_NONBLOCK,0);
    if (fd<0) { nova_putln("[nova-compositor] shell_ipc=WAITING reason=socket_failed"); return -1; }
    long rc=nova_bind((int)fd,&addr,sizeof(addr));
    if (rc<0) { nova_putln("[nova-compositor] shell_ipc=WAITING reason=bind_failed"); (void)nova_close((int)fd); return -1; }
    rc=nova_listen((int)fd,4);
    if (rc<0) { nova_putln("[nova-compositor] shell_ipc=WAITING reason=listen_failed"); (void)nova_close((int)fd); return -1; }
    nova_putln("[nova-compositor] shell_ipc=LISTENING protocol=1");
    return (int)fd;
}

static void log_scene_state(void) {
    put_key_u64("scene_generation",g_scene.scene_generation);
    put_key_u64("visual_generation",g_scene.visual_generation);
    put_key_u64("shell_ipc_messages",g_scene.ipc_messages);
    put_key_u64("focus_index",g_scene.focus_index);
    put_key_u64("window_x",g_scene.window_x<0?0UL:(unsigned long)g_scene.window_x);
    put_key_u64("window_y",g_scene.window_y<0?0UL:(unsigned long)g_scene.window_y);
}

static int consume_shell_message(int client, unsigned int width, unsigned int height) {
    struct nova_shell_message m;
    long n=nova_read(client,&m,sizeof(m));
    if (n==-NOVA_EAGAIN) return 1;
    if (n==0) return 0;
    if (n<0) return 0;
    if ((unsigned long)n!=sizeof(m) || m.magic!=NOVA_SHELL_PROTOCOL_MAGIC ||
        m.version!=NOVA_SHELL_PROTOCOL_VERSION || m.size!=sizeof(m)) {
        nova_putln("[nova-compositor] shell_ipc=REJECTED reason=protocol_message_invalid"); return 1;
    }
    g_scene.ipc_messages++; g_scene.protocol_version=m.version; g_scene.shell_sequence=m.sequence;
    if (m.opcode==NOVA_SHELL_OP_HELLO) {
        nova_putln("[nova-compositor] shell_ipc=CONNECTED protocol=1");
    } else if (m.opcode==NOVA_SHELL_OP_SCENE) {
        if (m.panel_height<24U||m.panel_height>160U||m.window_width<160U||m.window_height<120U||
            m.window_width>width||m.window_height>height) {
            nova_putln("[nova-compositor] shell_ipc=REJECTED reason=scene_limits_invalid"); return 1;
        }
        g_scene.panel_height=m.panel_height; g_scene.window_x=m.window_x; g_scene.window_y=m.window_y;
        g_scene.window_width=m.window_width; g_scene.window_height=m.window_height;
        /* Compositor owns placement. At UHD output, center the shell's logical
         * scene without altering the wire protocol or hit-test geometry. */
        if(g_r5_scale==2U && g_r5_logical_w>g_scene.window_width)
            g_scene.window_x=(int)((g_r5_logical_w-g_scene.window_width)/2U);
        if(g_r5_scale==2U && g_r5_logical_h>g_scene.window_height+180U)
            g_scene.window_y=(int)((g_r5_logical_h-g_scene.window_height)/3U);
        g_scene.accent_rgb=m.accent_rgb&0x00ffffffU; g_scene.focus_index=m.initial_focus?1U:0U;
        g_scene.configured=1; g_scene.scene_generation++; g_scene.visual_generation++; clamp_scene(width,height);
        nova_putln("[nova-compositor] scene=nova-shell-scene-v1"); log_scene_state();
    }
    return 1;
}

static int accept_shell_client(int listener, int old_client) {
    long client=nova_accept4(listener,NOVA_SOCK_NONBLOCK);
    if (client<0) return old_client;
    if (old_client>=0) (void)nova_close(old_client);
    g_scene.shell_connected=1;
    return (int)client;
}

static void disconnect_shell_client(int *client) {
    if (*client>=0) (void)nova_close(*client);
    *client=-1;
    if (g_scene.shell_connected) {
        g_scene.shell_connected=0; g_scene.shell_disconnects++;
        nova_putln("[nova-compositor] shell_ipc=DISCONNECTED scene_retained=yes");
        put_key_u64("shell_disconnects",g_scene.shell_disconnects);
    }
}

static void client_addr(struct nova_sockaddr_un *addr) {
    const char path[] = NOVA_SURFACE_SOCKET_PATH;
    nova_zero(addr,sizeof(*addr)); addr->sun_family=NOVA_AF_UNIX;
    for (unsigned long i=0;i<sizeof(path)&&i<sizeof(addr->sun_path);i++) addr->sun_path[i]=path[i];
}

static int setup_client_listener(void) {
    struct nova_sockaddr_un addr; client_addr(&addr);
    (void)nova_unlink(NOVA_SURFACE_SOCKET_PATH);
    long fd=nova_socket(NOVA_AF_UNIX,NOVA_SOCK_SEQPACKET|NOVA_SOCK_NONBLOCK,0);
    if (fd<0) { nova_putln("[nova-compositor] client_ipc=WAITING reason=socket_failed"); return -1; }
    long rc=nova_bind((int)fd,&addr,sizeof(addr));
    if (rc<0) { nova_putln("[nova-compositor] client_ipc=WAITING reason=bind_failed"); (void)nova_close((int)fd); return -1; }
    rc=nova_listen((int)fd,4);
    if (rc<0) { nova_putln("[nova-compositor] client_ipc=WAITING reason=listen_failed"); (void)nova_close((int)fd); return -1; }
    nova_putln("[nova-compositor] client_ipc=LISTENING protocol=6 lifecycle=toplevel-configure-ack widget-input=tab-capture-modifiers clipboard=bounded buffer_transport=memfd-scm-rights");
    return (int)fd;
}

static void sandbox_client_addr(struct nova_sockaddr_un *addr) {
    const char path[] = NOVA_SURFACE_SANDBOX_SOCKET_PATH;
    nova_zero(addr,sizeof(*addr)); addr->sun_family=NOVA_AF_UNIX;
    for (unsigned long i=0;i<sizeof(path)&&i<sizeof(addr->sun_path);i++) addr->sun_path[i]=path[i];
}

static void write_sandbox_ipc_state(const char *listener_state,const char *reason,int listener_fd) {
    long state_fd=nova_open_write("/run/nova/sandbox-ipc.state",0644);
    if(state_fd<0) return;
    nova_fd_putln((int)state_fd,"schema=1");
    nova_fd_puts((int)state_fd,"listener_state="); nova_fd_putln((int)state_fd,listener_state?listener_state:"UNKNOWN");
    nova_fd_puts((int)state_fd,"reason="); nova_fd_putln((int)state_fd,reason?reason:"none");
    nova_fd_putln((int)state_fd,"path=/run/nova/app/client.sock");
    nova_fd_putln((int)state_fd,"socket_mode=0666");
    nova_fd_putln((int)state_fd,"transport_auth=SO_PEERCRED_NOVAD_PRINCIPAL");
    nova_fd_puts((int)state_fd,"listener_fd="); nova_fd_put_u64((int)state_fd,listener_fd>=0?(unsigned long)listener_fd:0UL); nova_fd_putln((int)state_fd,"");
    (void)nova_fsync((int)state_fd);
    (void)nova_close((int)state_fd);
}

static int setup_sandbox_client_listener(void) {
    struct nova_sockaddr_un addr; sandbox_client_addr(&addr);
    write_sandbox_ipc_state("STARTING","none",-1);
    (void)nova_mkdir(NOVA_SURFACE_SANDBOX_SOCKET_DIR,0755);
    if(nova_fchmodat(NOVA_SURFACE_SANDBOX_SOCKET_DIR,0755)<0){
        nova_putln("[nova-compositor] sandbox_client_ipc=WAITING reason=runtime_dir_failed");
        write_sandbox_ipc_state("WAITING","runtime_dir_failed",-1);
        return -1;
    }
    (void)nova_unlink(NOVA_SURFACE_SANDBOX_SOCKET_PATH);
    long fd=nova_socket(NOVA_AF_UNIX,NOVA_SOCK_SEQPACKET|NOVA_SOCK_NONBLOCK,0);
    if(fd<0){
        nova_putln("[nova-compositor] sandbox_client_ipc=WAITING reason=socket_failed");
        write_sandbox_ipc_state("WAITING","socket_failed",-1);
        return -1;
    }
    long rc=nova_bind((int)fd,&addr,sizeof(addr));
    if(rc<0){
        nova_putln("[nova-compositor] sandbox_client_ipc=WAITING reason=bind_failed");
        write_sandbox_ipc_state("WAITING","bind_failed",-1);
        (void)nova_close((int)fd); return -1;
    }
    /* Pathname AF_UNIX connect() checks read/write permission on the socket inode.
     * Phase-17 applications intentionally run under unique unprivileged UIDs,
     * so the app-facing transport must be reachable independently of Unix UID.
     * This grants transport reachability only: SO_PEERCRED -> novad live-principal
     * authentication still authorizes every accepted application connection. */
    if(nova_fchmodat(NOVA_SURFACE_SANDBOX_SOCKET_PATH,0666)<0){
        nova_putln("[nova-compositor] sandbox_client_ipc=WAITING reason=socket_mode_failed");
        write_sandbox_ipc_state("WAITING","socket_mode_failed",-1);
        (void)nova_close((int)fd);
        (void)nova_unlink(NOVA_SURFACE_SANDBOX_SOCKET_PATH);
        return -1;
    }
    rc=nova_listen((int)fd,16);
    if(rc<0){
        nova_putln("[nova-compositor] sandbox_client_ipc=WAITING reason=listen_failed");
        write_sandbox_ipc_state("WAITING","listen_failed",-1);
        (void)nova_close((int)fd); return -1;
    }
    write_sandbox_ipc_state("LISTENING","none",(int)fd);
    nova_putln("[nova-compositor] sandbox_client_ipc=LISTENING path=/run/nova/app/client.sock protocol=6 mode=0666 backlog=16");
    return (int)fd;
}

static int validate_surface_message(const struct nova_surface_message *m) {
    return m && m->magic==NOVA_SURFACE_PROTOCOL_MAGIC && m->version==NOVA_SURFACE_PROTOCOL_VERSION &&
           m->size==sizeof(*m) && m->client_id!=0U;
}

static long recv_surface_packet(int client, struct nova_surface_message *m, int *received_fd) {
    struct nova_iovec iov;struct nova_msghdr msg;
    union {unsigned char bytes[NOVA_CMSG_SPACE(8U*sizeof(int))];struct nova_cmsghdr align;} control;
    nova_zero(&iov,sizeof(iov));nova_zero(&msg,sizeof(msg));nova_zero(&control,sizeof(control));
    *received_fd=-1;iov.iov_base=m;iov.iov_len=sizeof(*m);msg.msg_iov=&iov;msg.msg_iovlen=1;
    msg.msg_control=control.bytes;msg.msg_controllen=sizeof(control.bytes);
    long n=nova_recvmsg(client,&msg,NOVA_MSG_CMSG_CLOEXEC);if(n<0)return n;
    int fds[8];unsigned int count=0;int valid=1;unsigned long offset=0;
    while(offset+sizeof(struct nova_cmsghdr)<=msg.msg_controllen){
        struct nova_cmsghdr *cmsg=(struct nova_cmsghdr*)(control.bytes+offset);
        if(cmsg->cmsg_len<NOVA_CMSG_DATA_OFFSET||cmsg->cmsg_len>msg.msg_controllen-offset){valid=0;break;}
        unsigned long bytes=cmsg->cmsg_len-NOVA_CMSG_DATA_OFFSET;
        if(cmsg->cmsg_level!=NOVA_SOL_SOCKET||cmsg->cmsg_type!=NOVA_SCM_RIGHTS||bytes%sizeof(int)){valid=0;break;}
        for(unsigned long i=0;i<bytes/sizeof(int);i++){
            int fd;nova_copy(&fd,control.bytes+offset+NOVA_CMSG_DATA_OFFSET+i*sizeof(int),sizeof(fd));
            if(count<8U)fds[count++]=fd;else{nova_close(fd);valid=0;}
        }
        offset+=NOVA_CMSG_SPACE(bytes);
    }
    if(count>1U||n!=(long)sizeof(*m)||(msg.msg_flags&(NOVA_MSG_CTRUNC|NOVA_MSG_TRUNC)))valid=0;
    if(!valid){for(unsigned int i=0;i<count;i++)nova_close(fds[i]);return -1;}
    if(count==1U)*received_fd=fds[0];return n;
}

static int validate_client_buffer_descriptor(const struct nova_surface_message *m,
                                             unsigned int display_width, unsigned int display_height) {
    if (!m->buffer_id || !m->width || !m->height) return 0;
    if (m->width>display_width || m->height>display_height) return 0;
    if (m->pixel_format!=NOVA_PIXEL_FORMAT_XRGB8888) return 0;
    if (m->width>NOVA_SURFACE_MAX_BUFFER_BYTES/4U) return 0;
    if (m->stride!=m->width*4U || (m->stride&3U)) return 0;
    unsigned long long expected=(unsigned long long)m->stride*(unsigned long long)m->height;
    if (!expected || expected>NOVA_SURFACE_MAX_BUFFER_BYTES || m->buffer_bytes!=expected) return 0;
    return 1;
}

static struct nova_client_buffer *allocate_client_buffer_slot(void) {
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_BUFFERS;i++)
        if (!g_client_buffers[i].used) return &g_client_buffers[i];
    return (struct nova_client_buffer *)0;
}

static void destroy_client_buffer_entry(struct nova_client_buffer *buf) {
    if (!buf || !buf->used) return;
    if (buf->map && !pointer_is_error(buf->map) && buf->bytes)
        (void)nova_munmap(buf->map,(nova_size_t)buf->bytes);
    if (buf->fd>=0) (void)nova_close(buf->fd);
    nova_zero(buf,sizeof(*buf)); buf->fd=-1;
}

static int surface_references_buffer(unsigned int client_id, unsigned int buffer_id) {
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) {
        struct nova_client_surface *s=&g_surfaces[i];
        if (!s->used || s->client_id!=client_id) continue;
        if ((s->committed && s->buffer_id==buffer_id) || s->pending_buffer_id==buffer_id) return 1;
    }
    return 0;
}

static int client_buffer_budget_available(unsigned int client_id,unsigned long long bytes){
    unsigned long long total=0,own=0;unsigned int count=0;
    for(unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_BUFFERS;i++){
        if(!g_client_buffers[i].used)continue;
        total+=g_client_buffers[i].bytes;
        if(g_client_buffers[i].client_id==client_id){own+=g_client_buffers[i].bytes;count++;}
    }
    unsigned long long cap=16ULL*1024ULL*1024ULL;
    if(client_id==3U&&count>=2U)return 0;
    return bytes<=NOVA_SURFACE_MAX_BUFFER_BYTES && bytes<=cap && own<=cap-bytes && bytes<=32ULL*1024ULL*1024ULL &&
           total<=32ULL*1024ULL*1024ULL-bytes;
}

/* Do not mmap shrinkable, untrusted backing files in the display process.
 * Kernel pread copies at COMMIT into a bounded compositor-owned shadow. A failed
 * or truncated read leaves the last complete snapshot intact (no SIGBUS path). */
static int r17_refresh_client_buffer(struct nova_client_buffer *buf){
    if(!buf||buf->fd<0||!buf->bytes||buf->bytes>NOVA_SURFACE_MAX_BUFFER_BYTES)return 0;
    void *fresh=nova_mmap(0,(nova_size_t)buf->bytes,NOVA_PROT_READ|NOVA_PROT_WRITE,NOVA_MAP_PRIVATE|NOVA_MAP_ANONYMOUS,-1,0);
    if(pointer_is_error(fresh))return 0;
    unsigned long off=0;
    while(off<(unsigned long)buf->bytes){
        unsigned long chunk=(unsigned long)buf->bytes-off;if(chunk>65536UL)chunk=65536UL;
#if defined(__x86_64__)
        long n=nova_syscall4(17,buf->fd,(long)((unsigned char*)fresh+off),chunk,off); /* pread64 */
#else
        long n=nova_syscall4(67,buf->fd,(long)((unsigned char*)fresh+off),chunk,off);
#endif
        if(n==-NOVA_EINTR)continue;
        if(n<=0||(unsigned long)n>chunk){nova_munmap(fresh,(nova_size_t)buf->bytes);return 0;}
        off+=(unsigned long)n;
    }
    void *old=buf->map;buf->map=fresh;
    if(old&&!pointer_is_error(old))nova_munmap(old,(nova_size_t)buf->bytes);
    return 1;
}

static int register_client_buffer(int client, const struct nova_surface_message *m, int received_fd,
                                  unsigned int display_width, unsigned int display_height) {
    if (received_fd<0) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=create_buffer_fd_missing"); return 1; }
    if (!validate_client_buffer_descriptor(m,display_width,display_height)) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_descriptor_invalid"); (void)nova_close(received_fd); return 1;
    }
    if(!client_buffer_budget_available(m->client_id,m->buffer_bytes)){
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_budget");nova_close(received_fd);return 1;
    }
    if (find_client_buffer(m->client_id,m->buffer_id)) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_id_duplicate"); (void)nova_close(received_fd); return 1;
    }
    struct nova_client_buffer *slot=allocate_client_buffer_slot();
    if (!slot) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_registry_full"); (void)nova_close(received_fd); return 1; }
    long actual=nova_lseek(received_fd,0,NOVA_SEEK_END);
    if (actual<0 || (unsigned long long)actual!=m->buffer_bytes) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_backing_size_mismatch"); (void)nova_close(received_fd); return 1;
    }
    struct nova_statx descriptor;nova_zero(&descriptor,sizeof(descriptor));
    if(nova_syscall5(NOVA_NR_statx,received_fd,(long)"",NOVA_AT_EMPTY_PATH,NOVA_STATX_TYPE,(long)&descriptor)<0||
       !(descriptor.stx_mask&NOVA_STATX_TYPE)||(descriptor.stx_mode&NOVA_S_IFMT)!=NOVA_S_IFREG){
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_not_regular");nova_close(received_fd);return 1;
    }
    nova_zero(slot,sizeof(*slot)); slot->used=1; slot->owner_fd=client; slot->client_id=m->client_id;
    slot->buffer_id=m->buffer_id; slot->fd=received_fd; slot->map=0; slot->width=m->width; slot->height=m->height;
    slot->stride=m->stride; slot->pixel_format=m->pixel_format; slot->bytes=m->buffer_bytes;
    g_client.buffers_created++; g_client.buffer_generation++;
    nova_puts("[nova-compositor] client_buffer=CREATED id="); nova_put_u64(slot->buffer_id);
    nova_puts(" bytes="); nova_put_u64((unsigned long)slot->bytes); nova_putln(" transport=scm_rights");
    return 1;
}

static int destroy_client_buffer_request(int client, const struct nova_surface_message *m) {
    struct nova_client_buffer *buf=find_client_buffer(m->client_id,m->buffer_id);
    if (!buf || buf->owner_fd!=client) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_not_owned"); return 1; }
    if (surface_references_buffer(m->client_id,m->buffer_id)) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_busy"); return 1; }
    destroy_client_buffer_entry(buf); g_client.buffers_removed++; g_client.buffer_generation++;
    nova_putln("[nova-compositor] client_buffer=DESTROYED");
    return 1;
}

static int destroy_client_surface_request(int client, const struct nova_surface_message *m) {
    struct nova_client_surface *s=find_client_surface(m->surface_id);
    if (!s || s->owner_fd!=client || s->client_id!=m->client_id) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=surface_not_owned"); return 1;
    }
    if (g_client.focus_surface==s->surface_id) g_client.focus_surface=0U;
    if(g_files_path_drop.surface==s->surface_id)nova_path_drop_cancel(&g_files_path_drop);if (g_client.pointer_surface==s->surface_id) g_client.pointer_surface=0U;
    if (g_client_grab.surface_id==s->surface_id) clear_client_grab();
    if (g_clipboard.owner_client_id==s->client_id && g_clipboard.owner_surface_id==s->surface_id) clear_client_clipboard("surface_destroy");
    nova_zero(s,sizeof(*s));
    g_client.surfaces_removed++; g_client.explicit_surface_destroys++; g_client.surface_generation++; g_scene.visual_generation++;
    nova_puts("[nova-compositor] client_surface=DESTROYED id="); nova_put_u64(m->surface_id); nova_putln("");
    return 1;
}

static int set_surface_size_limits(struct nova_client_surface *surface, const struct nova_surface_message *m,
                                   unsigned int width, unsigned int height) {
    if (!m->min_width || !m->min_height || !m->max_width || !m->max_height ||
        m->min_width<NOVA_CLIENT_MIN_WIDTH || m->min_height<NOVA_CLIENT_MIN_HEIGHT ||
        m->min_width>m->max_width || m->min_height>m->max_height ||
        m->max_width>16384U || m->max_height>16384U ||
        m->min_width>width || m->min_height>height) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=toplevel_size_limits_invalid"); return 1;
    }
    surface->min_width=m->min_width; surface->min_height=m->min_height;
    surface->max_width=m->max_width<width?m->max_width:width; surface->max_height=m->max_height<height?m->max_height:height;
    return 1;
}

static int consume_client_message(int client, unsigned int width, unsigned int height) {
    struct nova_surface_message m;
    int received_fd=-1;
    long n=recv_surface_packet(client,&m,&received_fd);
    if (n==-NOVA_EAGAIN) return 1;
    if (n==0) return 0;
    if (n<0) { if (received_fd>=0) (void)nova_close(received_fd); return 0; }
    if ((unsigned long)n!=sizeof(m) || !validate_surface_message(&m)) {
        if (received_fd>=0) (void)nova_close(received_fd);
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=protocol_message_invalid");
        return 1;
    }
    struct nova_client_connection *conn=connection_for_fd(client);
    if (!conn) { if (received_fd>=0) (void)nova_close(received_fd); return 0; }
    if (!m.client_id) { if (received_fd>=0) (void)nova_close(received_fd); nova_putln("[nova-compositor] client_ipc=REJECTED reason=client_id_zero"); return 0; }
    if (!conn->authenticated) {
        if (m.opcode!=NOVA_SURFACE_OP_HELLO) {
            if (received_fd>=0) (void)nova_close(received_fd);
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=hello_required_before_authentication");
            return 0;
        }
        if (!authenticate_client_connection(conn,m.client_id)) {
            if (received_fd>=0) (void)nova_close(received_fd);
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=principal_authentication_failed");
            return 0;
        }
    } else if (conn->client_id!=m.client_id) {
        if (received_fd>=0) (void)nova_close(received_fd);
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=client_id_principal_mismatch");
        return 0;
    }
    g_client.messages++; g_client.protocol_version=m.version;
    if (m.opcode==NOVA_SURFACE_OP_HELLO) {
        if(m.input_flags&~(NOVA_SURFACE_FEATURE_THEME|NOVA_SURFACE_FEATURE_DESKTOP_OPEN)){if(received_fd>=0)nova_close(received_fd);return 0;}
        conn->theme_subscribed=(m.input_flags&NOVA_SURFACE_FEATURE_THEME)&&connection_has_capability(conn,NOVA_APP_CAP_UI_SURFACE);
        if((m.input_flags&NOVA_SURFACE_FEATURE_DESKTOP_OPEN)&&(conn->client_id!=3||!nova_streq(conn->app_id,"nova.files"))){if(received_fd>=0)nova_close(received_fd);return 0;}
        conn->desktop_open_subscribed=(m.input_flags&NOVA_SURFACE_FEATURE_DESKTOP_OPEN)!=0;
        r21_flush_theme(conn);
        if (received_fd>=0) (void)nova_close(received_fd);
        nova_puts("[nova-compositor] client_ipc=CONNECTED protocol=6 authenticated=yes client="); nova_put_u64(conn->client_id);
        nova_puts(" peer_pid="); nova_put_u64(conn->peer_pid);
        nova_puts(" generation="); nova_put_u64((unsigned long)conn->app_generation); nova_putln("");
        return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_HEARTBEAT) { if (received_fd>=0) (void)nova_close(received_fd); return 1; }
    if (m.opcode==NOVA_SURFACE_OP_CREATE_BUFFER)
        return register_client_buffer(client,&m,received_fd,width,height);
    if (received_fd>=0) {
        (void)nova_close(received_fd);
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=unexpected_fd");
        return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_DESTROY_BUFFER) return destroy_client_buffer_request(client,&m);
    if (!m.surface_id) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=surface_id_zero");
        return 1;
    }
    struct nova_client_surface *surface=find_client_surface(m.surface_id);
    if (m.opcode==NOVA_SURFACE_OP_CREATE_SURFACE) {
        surface=find_or_allocate_client_surface(client,m.client_id,m.surface_id);
        if (!surface) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=surface_registry_full_or_owned"); return 1; }
        if (m.width<NOVA_CLIENT_MIN_WIDTH || m.height<NOVA_CLIENT_MIN_HEIGHT || m.width>width || m.height>height) {
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=surface_limits_invalid"); return 1;
        }
        surface->pending_x=m.x; surface->pending_y=m.y; surface->pending_width=m.width; surface->pending_height=m.height;
        surface->pending_z_index=m.z_index; surface->max_width=width; surface->max_height=height;
        clamp_client_surface(surface,width,height);r21_flush_theme(conn); return 1;
    }
    if (!surface || surface->owner_fd!=client || surface->client_id!=m.client_id) {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=surface_not_owned"); return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_DESTROY_SURFACE) return destroy_client_surface_request(client,&m);
    if (m.opcode==NOVA_SURFACE_OP_SET_ROLE) {
        if (surface->committed || (surface->role && surface->role!=m.role) || m.role!=NOVA_SURFACE_ROLE_TOPLEVEL) {
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=toplevel_role_invalid"); return 1;
        }
        surface->role=m.role; return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_SET_TITLE) {
        if (surface->role!=NOVA_SURFACE_ROLE_TOPLEVEL) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=title_without_toplevel"); return 1; }
        copy_surface_title(surface->title,m.title); return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_SET_SIZE_LIMITS) {
        if (surface->role!=NOVA_SURFACE_ROLE_TOPLEVEL) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=size_limits_without_toplevel"); return 1; }
        return set_surface_size_limits(surface,&m,width,height);
    }
    if (m.opcode==NOVA_SURFACE_OP_SET_INPUT_FLAGS) {
        unsigned int allowed=NOVA_SURFACE_INPUT_CAPTURE_TAB|NOVA_SURFACE_INPUT_TEXT_ASCII|NOVA_SURFACE_INPUT_CLIPBOARD;
        if (m.input_flags&~allowed) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=input_flags_invalid"); return 1; }
        struct nova_client_connection *conn=connection_for_fd(client);
        if(!conn || !conn->authenticated || conn->client_id!=surface->client_id ||
           !requested_input_flags_authorized(conn,m.input_flags)) return 1;
        surface->input_flags=m.input_flags;
        nova_puts("[nova-compositor] surface_input_flags="); nova_put_u64(surface->surface_id);
        nova_puts(" flags="); nova_put_u64(surface->input_flags); nova_putln("");
        return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_DRAG_PATH) { if(!connection_has_capability(conn,NOVA_APP_CAP_UI_SURFACE))return 1; (void)nova_path_drop_offer(&g_files_path_drop,surface->client_id,surface->surface_id,surface->committed,m.clipboard,m.clipboard_length);return 1; }
    if (m.opcode==NOVA_SURFACE_OP_SET_CLIPBOARD) return set_client_clipboard(surface,&m);
    if (m.opcode==NOVA_SURFACE_OP_GET_CLIPBOARD) return get_client_clipboard(surface);
    if (m.opcode==NOVA_SURFACE_OP_ACK_CONFIGURE) {
        if (!surface->awaiting_configure || !m.configure_serial || m.configure_serial!=surface->configure_serial) {
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=configure_ack_serial_invalid"); return 1;
        }
        surface->acked_configure_serial=m.configure_serial; g_client.configure_acks++;
        nova_puts("[nova-compositor] configure_ack="); nova_put_u64(surface->surface_id);
        nova_puts(" serial="); nova_put_u64(m.configure_serial); nova_putln("");
        return 1;
    }
    if (m.opcode==NOVA_SURFACE_OP_SET_POSITION) {
        if (surface->committed && surface->role==NOVA_SURFACE_ROLE_TOPLEVEL) {
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=toplevel_position_client_controlled"); return 1;
        }
        surface->pending_x=m.x; surface->pending_y=m.y; surface->pending_z_index=m.z_index; clamp_client_surface(surface,width,height);
    } else if (m.opcode==NOVA_SURFACE_OP_ATTACH_BUFFER) {
        struct nova_client_buffer *buf=find_client_buffer(m.client_id,m.buffer_id);
        if (!buf || buf->owner_fd!=client) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_not_owned"); return 1; }
        if (buf->width<surface->min_width || buf->height<surface->min_height ||
            buf->width>surface->max_width || buf->height>surface->max_height) {
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_outside_toplevel_limits"); return 1;
        }
        surface->pending_buffer_id=buf->buffer_id; surface->pending_width=buf->width; surface->pending_height=buf->height;
        clamp_client_surface(surface,width,height);
    } else if (m.opcode==NOVA_SURFACE_OP_DAMAGE) {
        struct nova_client_buffer *buf=find_client_buffer(m.client_id,surface->pending_buffer_id?surface->pending_buffer_id:surface->buffer_id);
        if (!buf || m.damage_x<0 || m.damage_y<0 || !m.damage_width || !m.damage_height ||
            (unsigned int)m.damage_x>=buf->width || (unsigned int)m.damage_y>=buf->height ||
            m.damage_width>buf->width-(unsigned int)m.damage_x || m.damage_height>buf->height-(unsigned int)m.damage_y) {
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=damage_rect_invalid"); return 1;
        }
        surface->damage_x=m.damage_x; surface->damage_y=m.damage_y;
        surface->damage_width=m.damage_width; surface->damage_height=m.damage_height; g_client.damage_messages++;
    } else if (m.opcode==NOVA_SURFACE_OP_COMMIT) {
        struct nova_client_buffer *buf=find_client_buffer(m.client_id,surface->pending_buffer_id);
        if (surface->role!=NOVA_SURFACE_ROLE_TOPLEVEL) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=commit_without_toplevel_role"); return 1; }
        if (!buf || buf->owner_fd!=client) { nova_putln("[nova-compositor] client_ipc=REJECTED reason=commit_without_owned_buffer"); return 1; }
        if (surface->awaiting_configure) {
            if (surface->acked_configure_serial!=surface->configure_serial) {
                nova_putln("[nova-compositor] client_ipc=REJECTED reason=commit_before_configure_ack"); return 1;
            }
            if (buf->width!=surface->configure_width || buf->height!=surface->configure_height) {
                nova_putln("[nova-compositor] client_ipc=REJECTED reason=configure_buffer_size_mismatch"); return 1;
            }
        }
        if(!r17_refresh_client_buffer(buf)){
            nova_putln("[nova-compositor] client_ipc=REJECTED reason=buffer_snapshot_read_failed");return 1;
        }
        clamp_client_surface(surface,width,height);
        surface->x=surface->pending_x; surface->y=surface->pending_y;
        surface->width=buf->width; surface->height=buf->height;
        surface->z_index=surface->pending_z_index; surface->buffer_id=surface->pending_buffer_id;
        unsigned first_map=!surface->committed;surface->committed=1;
        if(first_map)r48_focus_new_surface(surface);
        if (surface->awaiting_configure) { surface->awaiting_configure=0; g_client.window_resizes++; }
        g_client.commits++; if (m.client_id<=3U) g_client_commits_by_id[m.client_id]++; g_client.surface_generation++; g_scene.visual_generation++;
        if(!NOVA_R24_OPTIMIZED||(m.client_id>=1U&&m.client_id<=3U&&g_client_commits_by_id[m.client_id]<=2U)){nova_puts("[nova-compositor] surface_commit="); nova_put_u64(surface->surface_id);
        nova_puts(" buffer="); nova_put_u64(surface->buffer_id);
        nova_puts(" size="); nova_put_u64(surface->width); nova_puts("x"); nova_put_u64(surface->height);
        nova_puts(" generation="); nova_put_u64(g_client.surface_generation); nova_putln("");}
    } else {
        nova_putln("[nova-compositor] client_ipc=REJECTED reason=opcode_unknown");
    }
    return 1;
}

static int accept_client_connection(int listener, int clients[NOVA_MAX_CLIENT_CONNECTIONS]) {
    long client=nova_accept4(listener,NOVA_SOCK_NONBLOCK);
    if (client<0) return 0;
    for (unsigned int i=0;i<NOVA_MAX_CLIENT_CONNECTIONS;i++) {
        if (clients[i]<0 && !g_connections[i].used) {
            unsigned int peer_pid=0U;
            if(!peer_pid_for_fd((int)client,&peer_pid)){
                (void)nova_close((int)client);
                nova_putln("[nova-compositor] client_connection=REJECTED reason=peer_credentials_unavailable");
                return 0;
            }
            clients[i]=(int)client; g_connections[i].used=1; g_connections[i].fd=(int)client;
            g_connections[i].client_id=0U; g_connections[i].peer_pid=peer_pid; g_connections[i].authenticated=0U;
            g_client.connected=1; if (!g_client.next_configure_serial) g_client.next_configure_serial=100U;
            nova_puts("[nova-compositor] client_connection=ACCEPTED slot="); nova_put_u64(i);
            nova_puts(" peer_pid="); nova_put_u64(peer_pid); nova_putln("");
            return 1;
        }
    }
    (void)nova_close((int)client); nova_putln("[nova-compositor] client_connection=REJECTED reason=connection_slots_full"); return 0;
}

static void disconnect_client_connection(int *client) {
    if (!client) return;
    int old=*client; struct nova_client_connection *conn=connection_for_fd(old);
    unsigned int old_client_id=conn?conn->client_id:0U;
    if (old>=0) (void)nova_close(old); *client=-1;
    unsigned long removed=0, buffers_removed=0;
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_SURFACES;i++) {
        if (g_surfaces[i].used && g_surfaces[i].owner_fd==old) {
            if (g_client.focus_surface==g_surfaces[i].surface_id) g_client.focus_surface=0U;
            if(g_files_path_drop.surface==g_surfaces[i].surface_id)nova_path_drop_cancel(&g_files_path_drop);if (g_client.pointer_surface==g_surfaces[i].surface_id) g_client.pointer_surface=0U;
            if (g_client_grab.surface_id==g_surfaces[i].surface_id) clear_client_grab();
            nova_zero(&g_surfaces[i],sizeof(g_surfaces[i])); removed++;
        }
    }
    for (unsigned int i=0;i<NOVA_SURFACE_MAX_CLIENT_BUFFERS;i++) {
        if (g_client_buffers[i].used && g_client_buffers[i].owner_fd==old) { destroy_client_buffer_entry(&g_client_buffers[i]); buffers_removed++; }
    }
    if (conn) nova_zero(conn,sizeof(*conn));
    g_client.disconnects++; g_client.surfaces_removed+=removed; g_client.buffers_removed+=buffers_removed; g_input_modifiers=0U;
    if (g_clipboard.owner_client_id==old_client_id) clear_client_clipboard("client_disconnect");
    if (removed) { g_client.surface_generation++; g_scene.visual_generation++; }
    if (buffers_removed) g_client.buffer_generation++;
    g_client.connected=client_connection_count()?1:0;
    nova_puts("[nova-compositor] client_ipc=DISCONNECTED surfaces_removed="); nova_put_u64(removed);
    nova_puts(" buffers_removed="); nova_put_u64(buffers_removed); nova_puts(" client_id="); nova_put_u64(old_client_id); nova_putln("");
}

/* R17 / R16 completion: every authenticated slot owns one distinct poll entry. */
static void setup_app_pollfds(struct nova_pollfd *fds,unsigned int base,
                             const int clients[NOVA_MAX_CLIENT_CONNECTIONS]){
    for(unsigned int ci=0;ci<NOVA_MAX_CLIENT_CONNECTIONS;ci++){
        fds[base+ci].fd=clients[ci];
        fds[base+ci].events=clients[ci]>=0?(NOVA_POLLIN|NOVA_POLLERR|NOVA_POLLHUP):0;
        struct nova_client_connection*c=connection_for_fd(clients[ci]);
        if(c&&((r21_theme_surface(c)&&c->theme_sent!=g_session_theme.generation)||r57_open_ready(c)))fds[base+ci].events|=4; /* POLLOUT */
        fds[base+ci].revents=0;
    }
}
static int consume_app_pollfds(struct nova_pollfd *fds,unsigned int base,
                              int clients[NOVA_MAX_CLIENT_CONNECTIONS],unsigned int w,unsigned int h){
    int changed=0;
    for(unsigned int ci=0;ci<NOVA_MAX_CLIENT_CONNECTIONS;ci++){
        if(clients[ci]<0)continue;
        unsigned int events=(unsigned int)fds[base+ci].revents;
        if(events&4U)r21_flush_theme(connection_for_fd(clients[ci]));
        /* Consume queued final packets before HUP; then clean the owner resources. */
        if(events&NOVA_POLLIN){
            changed=1;
            if(!consume_client_message(clients[ci],w,h))disconnect_client_connection(&clients[ci]);
        }else if(events&(NOVA_POLLERR|NOVA_POLLHUP)){
            changed=1;disconnect_client_connection(&clients[ci]);
        }
    }
    return changed;
}

static unsigned int open_input_set(struct nova_input_set *set) {
    char path[19];
    nova_zero(set, sizeof(*set));g_r24.input_count=0;g_r24.sync_count=0;
    for (int i = 0; i < 32 && set->count < NOVA_MAX_INPUT_FDS; i++) {
        input_event_path(path, i);
        long fd = nova_open_ro_nonblock(path);
        if (fd < 0) continue;
        int ev_version = 0;
        if (nova_ioctl((int)fd, NOVA_EVIOCGVERSION, &ev_version) == 0){
            int clock_id=1;if(nova_ioctl((int)fd,0x400445a0UL,&clock_id)==0&&g_r24.input_count<32)g_r24.input_fd[g_r24.input_count++]=(int)fd;
            set->fds[set->count++] = (int)fd;}
        else
            (void)nova_close((int)fd);
    }
    return set->count;
}

static void close_input_set(struct nova_input_set *set) {
    for (unsigned int i = 0; i < set->count; i++) (void)nova_close(set->fds[i]);
    set->count = 0;
}

static void log_input_state(const char *kind) {
    if(NOVA_R24_OPTIMIZED)return;unsigned long long start=nova_render_clock(1);
    nova_puts("[nova-compositor] input_kind="); nova_putln(kind);
    put_key_u64("input_events", g_render.input_events);
    put_key_u64("keyboard_events", g_render.keyboard_events);
    put_key_u64("pointer_events", g_render.pointer_events);
    put_key_u64("theme", g_render.theme);
    put_key_u64("visual_generation", g_scene.visual_generation);
    put_key_u64("presented_visual_generation", g_render.presented_visual_generation);
    put_key_u64("cursor_x", g_render.cursor_x < 0 ? 0UL : (unsigned long)g_render.cursor_x);
    put_key_u64("cursor_y", g_render.cursor_y < 0 ? 0UL : (unsigned long)g_render.cursor_y);
    put_key_u64("focus_index", g_scene.focus_index);
    put_key_u64("window_x", g_scene.window_x < 0 ? 0UL : (unsigned long)g_scene.window_x);
    put_key_u64("window_y", g_scene.window_y < 0 ? 0UL : (unsigned long)g_scene.window_y);
    unsigned long long end=nova_render_clock(1);if(end>=start)g_r24.log_ns+=end-start;
}

static int cursor_in_toplevel_title(const struct nova_client_surface *s) {
    if (!s || s->role!=NOVA_SURFACE_ROLE_TOPLEVEL || !s->committed) return 0;
    int local_x=g_render.cursor_x-s->x, local_y=g_render.cursor_y-s->y;
    if (local_x<0 || local_y<0 || local_x>=(int)s->width || local_y>=(int)s->height) return 0;
    return local_y<(int)NOVA_TOPLEVEL_TITLEBAR_HEIGHT;
}

static int r17_title_button_at(const struct nova_client_surface *s,int px,int py){
    if(!s||s->role!=NOVA_SURFACE_ROLE_TOPLEVEL||!s->committed||s->minimized||s->width<110U)return 0;
    int ly=py-s->y;if(ly<5||ly>=23)return 0;
    for(int button=1;button<=3;button++){
        int x=s->x+(int)s->width-6-button*24;
        if(px>=x&&px<x+18)return button; /* close, maximize, minimize */
    }
    return 0;
}
static int cursor_in_toplevel_close(const struct nova_client_surface *s){
    return r17_title_button_at(s,g_render.cursor_x,g_render.cursor_y)==1;
}

static int cursor_in_toplevel_resize_edge(const struct nova_client_surface *s) {
    if (!s || s->role!=NOVA_SURFACE_ROLE_TOPLEVEL || !s->committed) return 0;
    int local_x=g_render.cursor_x-s->x, local_y=g_render.cursor_y-s->y;
    if (local_x<0 || local_y<0 || local_x>=(int)s->width || local_y>=(int)s->height) return 0;
    return local_x>=(int)s->width-(int)NOVA_TOPLEVEL_RESIZE_EDGE ||
           local_y>=(int)s->height-(int)NOVA_TOPLEVEL_RESIZE_EDGE;
}

static void begin_client_grab(struct nova_client_surface *s, unsigned int mode) {
    if (!s || s->minimized || s->maximized) return;
    clear_client_grab(); g_client_grab.mode=mode; g_client_grab.surface_id=s->surface_id;
    g_client_grab.start_cursor_x=g_render.cursor_x; g_client_grab.start_cursor_y=g_render.cursor_y;
    g_client_grab.origin_x=s->x; g_client_grab.origin_y=s->y;
    g_client_grab.origin_width=s->width; g_client_grab.origin_height=s->height;
    g_client_grab.target_width=s->width; g_client_grab.target_height=s->height;
}

static void update_client_grab(unsigned int width, unsigned int height) {
    if (!g_client_grab.mode || !g_client_grab.surface_id) return;
    struct nova_client_surface *s=find_client_surface(g_client_grab.surface_id);
    if (!s || !s->committed) { clear_client_grab(); return; }
    int dx=g_render.cursor_x-g_client_grab.start_cursor_x;
    int dy=g_render.cursor_y-g_client_grab.start_cursor_y;
    if (g_client_grab.mode==NOVA_GRAB_MOVE) {
        s->pending_x=g_client_grab.origin_x+dx; s->pending_y=g_client_grab.origin_y+dy;
        s->pending_width=s->width; s->pending_height=s->height; clamp_client_surface(s,width,height);
        if (s->x!=s->pending_x || s->y!=s->pending_y) {
            s->x=s->pending_x; s->y=s->pending_y; g_client_grab.moved=1; g_scene.visual_generation++;
        }
    } else if (g_client_grab.mode==NOVA_GRAB_RESIZE) {
        long want_w=(long)g_client_grab.origin_width+dx;
        long want_h=(long)g_client_grab.origin_height+dy;
        unsigned int min_w=s->min_width? s->min_width:NOVA_CLIENT_MIN_WIDTH;
        unsigned int min_h=s->min_height? s->min_height:NOVA_CLIENT_MIN_HEIGHT;
        unsigned int max_w=s->max_width? s->max_width:width;
        unsigned int max_h=s->max_height? s->max_height:height;
        unsigned int screen_w=s->x>=0 && (unsigned int)s->x<width ? width-(unsigned int)s->x : min_w;
        unsigned int screen_h=s->y>=0 && (unsigned int)s->y<height ? height-(unsigned int)s->y : min_h;
        if (max_w>screen_w) max_w=screen_w; if (max_h>screen_h) max_h=screen_h;
        if (want_w<(long)min_w) want_w=(long)min_w; if (want_h<(long)min_h) want_h=(long)min_h;
        if (want_w>(long)max_w) want_w=(long)max_w; if (want_h>(long)max_h) want_h=(long)max_h;
        g_client_grab.target_width=(unsigned int)want_w; g_client_grab.target_height=(unsigned int)want_h;
        if (g_client_grab.target_width!=g_client_grab.origin_width || g_client_grab.target_height!=g_client_grab.origin_height)
            g_client_grab.moved=1;
    }
}

static void finish_client_grab(void) {
    if (!g_client_grab.mode || !g_client_grab.surface_id) { clear_client_grab(); return; }
    struct nova_client_surface *s=find_client_surface(g_client_grab.surface_id);
    if (s && s->committed && g_client_grab.moved) {
        if (g_client_grab.mode==NOVA_GRAB_MOVE) {
            g_client.window_moves++; g_client.surface_generation++;
            (void)send_surface_configure(s,s->width,s->height);
            nova_puts("[nova-compositor] toplevel_move="); nova_put_u64(s->surface_id);
            nova_puts(" x="); nova_put_u64(s->x<0?0UL:(unsigned long)s->x); nova_puts(" y="); nova_put_u64(s->y<0?0UL:(unsigned long)s->y); nova_putln("");
        } else if (g_client_grab.mode==NOVA_GRAB_RESIZE) {
            (void)send_surface_configure(s,g_client_grab.target_width,g_client_grab.target_height);
        }
    }
    clear_client_grab();
}


